/** 삭제/제한 타겟을 seen 에 넣어 재수집·재시도 루프를 끊는다 */
function markTerafabxHomeVerifiedTargetDiscarded(targetUrl, meta = {}) {
  const id = parseXStatusUrl(targetUrl)?.id;
  if (!id) return { ok: false };
  const state = loadTerafabxState();
  const seen = Array.from(new Set([id, ...(state.homeVerifiedCommentSeenIds || [])])).slice(0, 5000);
  saveTerafabxState({
    homeVerifiedCommentSeenIds: seen,
    homeVerifiedCommentLastDeadTargetDiscardAt: new Date().toISOString(),
    homeVerifiedCommentLastDeadTargetDiscard: {
      targetUrl: normalizeXStatusUrl(targetUrl),
      id,
      reason: meta.reason || null,
      error: String(meta.error || "").slice(0, 400),
      attempts: meta.attempts || null,
      at: new Date().toISOString(),
    },
  });
  return { ok: true, id };
}

/** 큐에 쌓인 영구 실패 타겟 일괄 폐기 (재시도 루프 청소) */
function purgeHomeVerifiedDeadTargetPending(options = {}) {
  const maxAttempts = Math.max(1, Number(options.maxAttempts || process.env.TERAFABX_HOME_VERIFIED_MAX_POST_ATTEMPTS || 5));
  const rows = loadTerafabxHomeVerifiedWriteQueue();
  const kept = [];
  const purged = [];
  for (const row of rows) {
    const disposition = homeVerifiedCommentLib.homeVerifiedPostFailureDisposition(row.lastError || "", {
      attempts: Math.max(0, Number(row.attempts || 0)),
      maxAttempts,
    });
    // rate_limit 은 attempts 많아도 유지. disposition.discard 만 폐기.
    if (disposition.discard) {
      markTerafabxHomeVerifiedTargetDiscarded(row.targetUrl, {
        reason: disposition.reason,
        error: row.lastError,
        attempts: row.attempts,
      });
      purged.push({
        id: row.id,
        targetUrl: row.targetUrl,
        authorHandle: row.authorHandle,
        reason: disposition.reason,
        attempts: row.attempts,
        lastError: String(row.lastError || "").slice(0, 200),
      });
      continue;
    }
    kept.push(row);
  }
  if (purged.length) {
    saveTerafabxHomeVerifiedWriteQueue(kept);
    logEvent("terafabx_home_verified_dead_target_purge", {
      purged: purged.length,
      remaining: kept.length,
      sample: purged.slice(0, 12),
    });
  }
  return {
    purged: purged.length,
    remaining: kept.length,
    items: purged.slice(0, Number(options.sample || 30)),
  };
}

function terafabxHomeVerifiedAlreadyHandled(state, targetUrl) {
  const id = parseXStatusUrl(targetUrl)?.id;
  if (!id) return true;
  if ((state.homeVerifiedCommentSeenIds || []).includes(id)) return true;
  if ((state.homeVerifiedCommentHistory || []).some((item) => parseXStatusUrl(item?.targetUrl || item?.url || "")?.id === id)) return true;
  if ((state.commentHistory || []).some((item) => (
    item?.source === TERAFABX_HOME_VERIFIED_COMMENT_SOURCE
    && parseXStatusUrl(item?.targetUrl || item?.url || "")?.id === id
  ))) return true;
  if (loadTerafabxHomeVerifiedWriteQueue().some((row) => parseXStatusUrl(row.targetUrl || "")?.id === id)) return true;
  return false;
}

function buildTerafabxHomeVerifiedCommentTarget(post) {
  return homeVerifiedCommentLib.buildHomeVerifiedCommentTarget(post, homeVerifiedCommentHelpers());
}

function classifyTerafabxHomeVerifiedOriginalCandidate(raw, options = {}) {
  return homeVerifiedCommentLib.classifyHomeVerifiedOriginalCandidate(raw, {
    ...options,
    helpers: homeVerifiedCommentHelpers(),
    requiredHandle: REQUIRED_X_HANDLE,
    // 공통 민감 주제 + 홈 전용 욕설/비난/논란 게이트
    bannedRe: options.bannedRe || TERAFABX_COMMENT_TARGET_BANNED_RE,
  });
}

function selectTerafabxHomeVerifiedOriginalCandidates(items, options = {}) {
  return homeVerifiedCommentLib.selectHomeVerifiedOriginalCandidates(items, {
    ...options,
    helpers: homeVerifiedCommentHelpers(),
    requiredHandle: REQUIRED_X_HANDLE,
    bannedRe: options.bannedRe || TERAFABX_COMMENT_TARGET_BANNED_RE,
  });
}

function ingestTerafabxHomeVerifiedCandidates(items = [], options = {}) {
  const state = loadTerafabxState();
  const seenIds = new Set([
    ...(state.homeVerifiedCommentSeenIds || []),
    ...((state.homeVerifiedCommentHistory || []).map((item) => parseXStatusUrl(item?.targetUrl || "")?.id).filter(Boolean)),
  ]);
  const { selected, rejected } = selectTerafabxHomeVerifiedOriginalCandidates(items, {
    seenIds,
    limit: Number(options.limit || TERAFABX_HOME_VERIFIED_COMMENT_BATCH_LIMIT * 4),
  });
  const existing = homeVerifiedCommentLib.normalizeHomeVerifiedCandidateBacklog(
    state.homeVerifiedCommentBacklog,
    homeVerifiedCommentHelpers(),
  );
  const byId = new Map(existing.map((item) => [item.id, item]));
  for (const post of selected) {
    if (terafabxHomeVerifiedAlreadyHandled(state, post.url)) continue;
    byId.set(post.id, { ...post, discoveredAt: new Date().toISOString(), stage: "candidate", source: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE });
  }
  const backlog = Array.from(byId.values()).slice(0, 200);
  saveTerafabxState({ homeVerifiedCommentBacklog: backlog });
  logEvent("terafabx_home_verified_candidates_ingested", {
    input: Array.isArray(items) ? items.length : 0,
    selected: selected.length,
    rejected: rejected.length,
    backlog: backlog.length,
  });
  return { selected, rejected, backlogCount: backlog.length };
}

async function enrichHomeVerifiedCandidateFromApi(url) {
  const metadata = await fetchFxTwitterTweetMetadata(url);
  return classifyTerafabxHomeVerifiedOriginalCandidate(metadata);
}

/**
 * 팔로잉 타임라인 합성 수집 → 개인 파란체크 원글만 homeVerified backlog 적재.
 * 운영 Chrome 9224를 쓰지 않음 (격리 안전). 홈 DOM 수집은 별도 chromePort 있을 때 optional.
 */
function tallyHomeVerifiedRejectReasons(rejected = []) {
  return homeVerifiedCommentLib.tallyHomeVerifiedRejectReasons(rejected);
}

/** 큐에서 정책 하드페일 초안 제거 (게시 전 품질 피드백) */
function purgeHomeVerifiedPolicyFailPending(options = {}) {
  const rows = loadTerafabxHomeVerifiedWriteQueue();
  const kept = [];
  const purged = [];
  for (const row of rows) {
    const comment = row?.prepared?.comment || "";
    const judge = row?.prepared?.geminiReview?.finalJudge || { passed: true, qualityFlagsComplete: true, qualityFlags: {} };
    const hard = homeVerifiedCommentLib.homeVerifiedJudgeHardFail(judge, comment);
    const quality = assessTerafabxHomeVerifiedWriteQuality({ prepared: row.prepared, target: row.target });
    if (!hard.ok || !quality.ok) {
      purged.push({
        id: row.id,
        targetUrl: row.targetUrl,
        authorHandle: row.authorHandle,
        comment,
        reasons: hard.ok ? quality.errors : hard.reasons,
      });
      continue;
    }
    kept.push(row);
  }
  if (purged.length) {
    saveTerafabxHomeVerifiedWriteQueue(kept);
    logEvent("terafabx_home_verified_policy_purge", {
      purged: purged.length,
      remaining: kept.length,
      sample: purged.slice(0, 8),
    });
  }
  return { purged: purged.length, remaining: kept.length, items: purged.slice(0, Number(options.sample || 20)) };
}

async function discoverTerafabxHomeVerifiedCandidates(options = {}) {
  const limit = Math.max(1, Number(options.limit || TERAFABX_HOME_VERIFIED_COMMENT_DISCOVER_LIMIT || Math.max(12, TERAFABX_HOME_VERIFIED_COMMENT_BATCH_LIMIT * 3)));
  const maxCheck = Math.max(limit, Number(options.maxCheck || Math.max(120, limit * 2)));
  logEvent("terafabx_home_verified_discover_start", {
    limit,
    maxCheck,
    source: options.source || TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE || "fxtwitter-following",
  });

  let raw = [];
  if (options.candidates && Array.isArray(options.candidates) && options.candidates.length) {
    raw = options.candidates;
  } else {
    const collected = await collectTerafabxFxTwitterFollowingCandidates({
      persist: options.persist !== false,
      batchSize: options.batchSize || 40,
      concurrency: options.concurrency || 5,
    });
    raw = Array.isArray(collected.candidates) ? collected.candidates : [];
  }

  // 소수 작성자 도배 시 enrich 낭비 방지: 핸들 1인 1건 우선
  // maxCheck보다 넓게 diversify 한 뒤, pre-filter로 탈락한 슬롯을 채운다
  const preDiversifyCap = Math.max(maxCheck * 2, maxCheck + 80);
  const diversified = homeVerifiedCommentLib.diversifyHomeVerifiedDiscoverCandidates(raw, preDiversifyCap);
  const uniqueAuthorFirst = diversified.length;
  const classified = [];
  const rejected = [];
  const seenHandles = new Set();
  let skippedDuplicateAuthor = 0;
  let preFiltered = 0;
  let enriched = 0;
  for (const item of diversified) {
    if (classified.length >= limit) break;
    if (enriched >= maxCheck) break;
    const url = normalizeXStatusUrl(item.url || item.targetUrl || "");
    if (!url) continue;
    // URL 핸들만으로 배치 중복이면 enrich 스킵 (공급 효율)
    const urlHandle = String(
      item.authorHandle || item.handle || homeVerifiedCommentLib.authorHandleFromUrl(url) || "",
    ).replace(/^@/, "").toLowerCase();
    if (urlHandle && seenHandles.has(urlHandle)) {
      skippedDuplicateAuthor += 1;
      rejected.push({ url, reasons: ["author_already_in_batch"] });
      continue;
    }
    // enrich 전 텍스트 사전 필터 (following 스니펫만으로 탈락 가능한 경우)
    const snippet = cleanSocialText(item.text || item.targetText || "");
    if (snippet) {
      const preSafety = homeVerifiedCommentLib.assessHomeVerifiedOriginalContentSafety(snippet, {
        authorHandle: urlHandle,
      });
      if (!preSafety.ok) {
        preFiltered += 1;
        rejected.push({ url, reasons: [preSafety.reason || "prefilter_content_safety"] });
        continue;
      }
      if (homeVerifiedCommentLib.isHomeVerifiedLinkOrSpaceOnlyWeakText(snippet)) {
        preFiltered += 1;
        rejected.push({ url, reasons: ["link_or_space_only_weak_text"] });
        continue;
      }
      if (homeVerifiedCommentLib.isHomeVerifiedCryptoSpamHandle(urlHandle)) {
        preFiltered += 1;
        rejected.push({ url, reasons: ["crypto_spam_handle"] });
        continue;
      }
    }
    try {
      enriched += 1;
      const live = await enrichHomeVerifiedCandidateFromApi(url);
      if (!live.ok) {
        rejected.push({ url, reasons: live.reasons });
        continue;
      }
      const handle = String(live.post.authorHandle || urlHandle || "").toLowerCase();
      if (handle && seenHandles.has(handle)) {
        skippedDuplicateAuthor += 1;
        rejected.push({ url, reasons: ["author_already_in_batch"] });
        continue;
      }
      if (handle) seenHandles.add(handle);
      classified.push({
        ...live.post,
        text: live.post.text || item.text || "",
        source: item.source || "fxtwitter-following-personal",
        discoveredAt: new Date().toISOString(),
      });
    } catch (error) {
      rejected.push({ url, reasons: ["metadata_error"], error: error.message });
    }
  }

  const ingested = ingestTerafabxHomeVerifiedCandidates(classified, { limit });
  const rejectReasonCounts = tallyHomeVerifiedRejectReasons(rejected);
  const summary = {
    scanned: raw.length,
    checked: enriched + preFiltered + skippedDuplicateAuthor,
    enriched,
    preFiltered,
    uniqueAuthorFirst,
    personalSelected: classified.length,
    rejected: rejected.length,
    skippedDuplicateAuthor,
    rejectReasonCounts,
    yieldRate: enriched
      ? Math.round((classified.length / enriched) * 1000) / 1000
      : 0,
    enrichYieldRate: enriched
      ? Math.round((classified.length / enriched) * 1000) / 1000
      : 0,
    backlogCount: ingested.backlogCount,
    sampleRejected: rejected.slice(0, 12),
    source: options.source || TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE || "fxtwitter-following",
  };
  saveTerafabxState({
    homeVerifiedCommentLastDiscoveryAt: new Date().toISOString(),
    homeVerifiedCommentLastDiscoverySummary: summary,
  });
  logEvent("terafabx_home_verified_discover_done", summary);
  return { ok: true, ...summary, selected: classified.slice(0, limit) };
}

function assessTerafabxHomeVerifiedWriteQuality(record = {}) {
  // 초안 품질(길이·문체·클리셰)은 LLM 프롬프트+judge만. 여기는 안전 금칙 + judge 결과만.
  return homeVerifiedCommentLib.assessHomeVerifiedWriteQuality(record, {
    cleanSocialText,
    bannedRe: TERAFABX_COMMENT_TARGET_BANNED_RE,
  });
}

function resolveHomeVerifiedContextProvider(options = {}) {
  const raw = String(options.contextProvider || TERAFABX_HOME_VERIFIED_CONTEXT_PROVIDER || "gemini").toLowerCase().trim();
  if (raw === "web" || raw === "grok" || raw === "grok-web") return "web";
  if (raw === "cli" || raw === "grok-cli") return "cli";
  return "gemini";
}

function isConfirmedHomeVerifiedContext(value) {
  const provider = String(value?.provider || "");
  // gemini-web-context: 홈 전용 text-only 1단계. web/cli-context: Grok 폴백.
  return hasDetailedTerafabxGrokContext(value)
    && /^(?:(?:web|cli)-context(?:-batch)?|direct-codex-context|gemini-web-context(?:-text)?)$/.test(provider)
    && !isTerafabxGrokContextFallback(value)
    && value?.rawPreview !== "local-root-context-fallback";
}

function assertConfirmedHomeVerifiedContext(value) {
  if (!isConfirmedHomeVerifiedContext(value)) {
    const error = new Error("홈 원글 검증 문맥/초안이 없어 진행하지 않습니다.");
    error.code = "TERAFABX_HOME_VERIFIED_CONTEXT_REQUIRED";
    throw error;
  }
  return value;
}

// 길이/톤 trim·polish는 사용하지 않음. stage1 초안을 그대로 쓴다.

/**
 * 홈 원글 문맥+초안 1단계: Gemini headless · 원글 텍스트-only (기본).
 * Grok 쿼타를 쓰지 않는다. URL fetch/vision 없음.
 */
async function analyzeHomeVerifiedContextWithGemini(target, options = {}) {
  const timeoutMs = Math.max(60_000, Number(options.timeoutMs || 180_000));
  const maxAttempts = Math.max(1, Math.min(Number(options.maxAttempts || 2), 2));
  const chromePort = Number(options.chromePort || TERAFABX_HOME_VERIFIED_COMMENT_GEMINI_PORT_BASE);
  const profileDir = options.profileDir || `${TERAFABX_GEMINI_PROFILE_DIR}-home-verified-1`;
  const runId = `terafabx-home-verified-gemini-context-${new Date().toISOString().replace(/[:.]/g, "-")}-${target.targetId || "target"}`;
  const runDir = path.join(TERAFABX_GEMINI_REVIEW_DIR, runId);
  fs.mkdirSync(runDir, { recursive: true });
  logEvent("terafabx_home_verified_gemini_context_start", {
    targetUrl: target.url,
    textLength: String(target.targetText || "").length,
    port: chromePort,
    runDir,
  });
  const scriptPath = resolveTerafabxGeminiScriptPath();
  if (!fs.existsSync(scriptPath)) throw new Error(`Gemini Web 스크립트가 없습니다: ${scriptPath}`);
  await ensureTerafabxGeminiHeadlessBrowser({ port: chromePort, profileDir });
  try {
    for (const [attempt, extraRule] of [
      [1, "텍스트-only. 원문 본문만 보고 12~30자 짧은 맞장구. 고유 명사·키워드를 일부러 끼워 넣지 마라."],
      [2, "문맥이 애매하면 추정이라고 쓰고, 본문에서 확인되는 포인트만 12~30자 맞장구로 써라. 명사 박제 금지."],
    ].slice(0, maxAttempts)) {
      try {
        const requestId = `hvc-gem-${crypto.randomUUID()}`;
        const prompt = homeVerifiedCommentPrompts.homeVerifiedGrokContextPrompt(target, extraRule, requestId);
        const promptPath = path.join(runDir, `attempt-${attempt}-prompt.md`);
        const outPath = path.join(runDir, `attempt-${attempt}-out.txt`);
        fs.writeFileSync(promptPath, prompt);
        const result = await runTerafabxGeminiScript(
          scriptPath,
          ["--prompt", promptPath, "--out", outPath, "--cdp", `http://127.0.0.1:${chromePort}`, "--min-length", "20"],
          {
            cwd: terafabxGeminiScriptCwd(scriptPath),
            timeoutMs,
            chromePort,
            profileDir,
            priority: options.priority || options.geminiPriority || "home-verified",
            label: `home-verified-context:${target.targetId || "target"}:${attempt}`,
          },
        );
        fs.writeFileSync(path.join(runDir, `attempt-${attempt}.stdout.txt`), result.stdout || "");
        fs.writeFileSync(path.join(runDir, `attempt-${attempt}.stderr.txt`), result.stderr || "");
        if (result.code !== 0) throw new Error(result.stderr || result.stdout || "홈 원글 Gemini 문맥 생성 실패");
        if (!fs.existsSync(outPath)) throw new Error("홈 원글 Gemini 문맥 출력 파일이 없습니다.");
        const raw = fs.readFileSync(outPath, "utf8");
        const parsed = parseTerafabxGrokContext(raw);
        if (!hasDetailedTerafabxGrokContext(parsed) || !parsed.reply) {
          throw new Error("홈 원글 Gemini 문맥/초안 JSON이 비어 있거나 부족합니다.");
        }
        const finalResult = {
          ...parsed,
          provider: "gemini-web-context",
          mode: "home_verified_original",
          pipeline: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
          runDir,
        };
        logEvent("terafabx_home_verified_gemini_context_ok", {
          attempt,
          targetUrl: target.url,
          contextPreview: finalResult.contextSummary.slice(0, 240),
          reply: finalResult.reply,
          runDir,
        });
        return finalResult;
      } catch (error) {
        logEvent("terafabx_home_verified_gemini_context_attempt_failed", {
          attempt,
          targetUrl: target.url,
          error: error.message,
          runDir,
        });
        if (attempt >= maxAttempts) throw error;
      }
    }
    throw new Error("홈 원글 Gemini 문맥·초안 생성 실패");
  } finally {
    // prepare 전체에서 같은 브라우저로 review까지 이어갈 수 있게 기본 유지.
    // cleanup은 buildHomeVerifiedPreparedCommentRecord / review 쪽에서 담당.
    if (options.cleanupBrowser === true) {
      await closeTerafabxGeminiHeadlessBrowser({ port: chromePort, profileDir }).catch(() => null);
    }
  }
}

/** 홈 원글 전용 Grok 폴백 — own-post/terafabxGrokContextPrompt 를 호출하지 않음 */
async function analyzeHomeVerifiedContextWithGrok(target, options = {}) {
  const provider = options.contextProvider === "cli" || TERAFABX_GROK_PROVIDER === "cli" ? "cli" : "web";
  const timeoutMs = Number(options.timeoutMs || 90_000);
  const maxAttempts = Math.max(1, Math.min(Number(options.maxAttempts || 2), 2));
  const session = options.session || `${TERAFABX_GROK_WEB_SESSION}-home-verified`;
  logEvent("terafabx_home_verified_grok_start", {
    provider,
    targetUrl: target.url,
    textLength: String(target.targetText || "").length,
  });
  for (const [attempt, extraRule] of [
    [1, "텍스트-only. 원문 본문만 보고 12~30자 짧은 맞장구. 고유 명사·키워드를 일부러 끼워 넣지 마라."],
    [2, "문맥이 애매하면 추정이라고 표시하고 원글 텍스트에서 확인되는 포인트만 써라. 명사 박제 금지."],
  ].slice(0, maxAttempts)) {
    try {
      const requestId = `hvc-${crypto.randomUUID()}`;
      const prompt = homeVerifiedCommentPrompts.homeVerifiedGrokContextPrompt(target, extraRule, requestId);
      const raw = provider === "web"
        ? await runGrokWebAgent(prompt, {
          attempt,
          targetId: `${target.targetId || "target"}-home-verified`,
          targetUrl: target.url,
          timeoutMs: options.timeoutMs ? timeoutMs : Math.max(timeoutMs, TERAFABX_GROK_WEB_TIMEOUT_MS),
          session,
          skipStateSync: Boolean(options.skipGrokStateSync),
        })
        : await runGrokCli(prompt, timeoutMs);
      if (isTerafabxGrokNonJsonLimitText(raw)) {
        const error = new Error("Grok 문맥 응답이 JSON이 아닌 limit 문구입니다.");
        error.code = "TERAFABX_GROK_CONTEXT_LIMIT_TEXT";
        error.noRetry = true;
        throw error;
      }
      const result = parseTerafabxGrokContext(raw);
      if (!hasDetailedTerafabxGrokContext(result) || !result.reply) {
        throw new Error("홈 원글 Grok 문맥/초안 JSON이 비어 있거나 부족합니다.");
      }
      logEvent("terafabx_home_verified_grok_ok", {
        provider,
        attempt,
        targetUrl: target.url,
        contextPreview: result.contextSummary.slice(0, 240),
        reply: result.reply,
      });
      return {
        ...result,
        provider: `${provider}-context`,
        mode: "home_verified_original",
        pipeline: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
      };
    } catch (error) {
      logEvent("terafabx_home_verified_grok_attempt_failed", {
        provider,
        attempt,
        targetUrl: target.url,
        error: error.message,
      });
      if (error.noRetry) throw error;
    }
  }
  throw new Error("홈 원글 Grok 문맥·초안 생성 실패");
}

/** 홈 원글 문맥+초안 1단계 라우터 (기본: gemini text-only) */
async function analyzeHomeVerifiedContext(target, options = {}) {
  const provider = resolveHomeVerifiedContextProvider(options);
  if (provider === "gemini") {
    return analyzeHomeVerifiedContextWithGemini(target, options);
  }
  return analyzeHomeVerifiedContextWithGrok(target, { ...options, contextProvider: provider });
}

/** 홈 원글 전용 Gemini 검수·최종 심사 — 대댓글 프롬프트 미사용 */
async function reviewHomeVerifiedReplyWithGemini(target, grokInput, options = {}) {
  const grok = normalizeTerafabxGrokResult(grokInput);
  if (!TERAFABX_GEMINI_REVIEW_ENABLED) {
    return { finalReply: grok.reply, usedGemini: false, disabled: true, finalJudge: { passed: true, score: 70, qualityFlagsComplete: true } };
  }
  const reviewId = `terafabx-home-verified-gemini-${new Date().toISOString().replace(/[:.]/g, "-")}-${target.targetId || "target"}`;
  const runDir = path.join(TERAFABX_GEMINI_REVIEW_DIR, reviewId);
  fs.mkdirSync(runDir, { recursive: true });
  const promptPath = path.join(runDir, "prompt.md");
  const outPath = path.join(runDir, "gemini-review.txt");
  const chromePort = Number(options.chromePort || TERAFABX_HOME_VERIFIED_COMMENT_GEMINI_PORT_BASE);
  const profileDir = options.profileDir || `${TERAFABX_GEMINI_PROFILE_DIR}-home-verified-1`;
  fs.writeFileSync(promptPath, homeVerifiedCommentPrompts.homeVerifiedGeminiReviewPrompt(target, grok));
  logEvent("terafabx_home_verified_gemini_review_start", {
    targetUrl: target.url,
    grokReply: grok.reply,
    port: chromePort,
    runDir,
  });
  try {
    await ensureTerafabxGeminiHeadlessBrowser({ port: chromePort, profileDir });
    const scriptPath = resolveTerafabxGeminiScriptPath();
    if (!fs.existsSync(scriptPath)) throw new Error(`Gemini Web 스크립트가 없습니다: ${scriptPath}`);
    const runScript = async (pPath, oPath, label) => runTerafabxGeminiScript(
      scriptPath,
      ["--prompt", pPath, "--out", oPath, "--cdp", `http://127.0.0.1:${chromePort}`, "--min-length", "6"],
      {
        cwd: terafabxGeminiScriptCwd(scriptPath),
        timeoutMs: 240000,
        chromePort,
        profileDir,
        priority: options.priority || options.geminiPriority,
        label,
      },
    );
    const judgeOnce = async (finalReply, attempt = 0) => {
      const judgeId = `final-judge-${attempt}`;
      const judgePromptPath = path.join(runDir, `${judgeId}-prompt.md`);
      const judgeOutPath = path.join(runDir, `${judgeId}.txt`);
      fs.writeFileSync(judgePromptPath, homeVerifiedCommentPrompts.homeVerifiedFinalJudgePrompt(target, grok, finalReply));
      const judgeRun = await runScript(judgePromptPath, judgeOutPath, `home-verified-judge:${target.targetId || "target"}:${attempt}`);
      if (judgeRun.code !== 0 || !fs.existsSync(judgeOutPath)) {
        throw new Error(judgeRun.stderr || judgeRun.stdout || "홈 원글 Gemini 최종 심사 실패");
      }
      const groundingContext = options.groundingContext || grok;
      let judged = parseTerafabxFinalJudge(fs.readFileSync(judgeOutPath, "utf8"), finalReply, {
        ...target,
        groundingContext,
      });
      // 100점대 + 앵커 엄격 매칭만 실패하는 홈 원글 오탈락 복구
      const reconciled = homeVerifiedCommentLib.reconcileHomeVerifiedFinalJudge(judged, {
        ...target,
        groundingContext,
      }, finalReply);
      if (reconciled.softGrounding) {
        logEvent("terafabx_home_verified_judge_soft_grounding", {
          targetUrl: target.url,
          finalReply,
          score: reconciled.score,
          method: reconciled.sourceAnchorGrounding?.method || null,
          recoveredFrom: reconciled.sourceAnchorGrounding?.recoveredFrom || null,
          attempt,
        });
      }
      judged = reconciled;
      return { ...judged, provider: "gemini-web-home-verified-judge", runDir };
    };

    // stage1 초안 우선 심사. 정책 하드페일(템플릿/cross-post 등)이면 rewrite 1회, 그래도 실패면 discard.
    const stage1Draft = grok.reply;
    let finalReply = stage1Draft;
    let decision = "keep_stage1";
    let finalJudge = await judgeOnce(stage1Draft, 0);
    let hard = homeVerifiedCommentLib.homeVerifiedJudgeHardFail(finalJudge, finalReply);

    const needsRewrite = !finalJudge.passed || !hard.ok;
    if (needsRewrite && Number(options.repairAttempt || 0) < 1) {
      const result = await runScript(promptPath, outPath, `home-verified-review:${target.targetId || "target"}`);
      fs.writeFileSync(path.join(runDir, "gemini.stdout.txt"), result.stdout || "");
      fs.writeFileSync(path.join(runDir, "gemini.stderr.txt"), result.stderr || "");
      if (result.code !== 0) throw new Error(result.stderr || result.stdout || "홈 원글 Gemini 검수 실패");
      if (!fs.existsSync(outPath)) throw new Error("홈 원글 Gemini 검수 출력 파일이 없습니다.");
      const review = parseTerafabxGeminiReview(fs.readFileSync(outPath, "utf8"));
      const rewritten = validateTerafabxReply(review.finalReply || stage1Draft);
      const rewriteJudge = await judgeOnce(rewritten, 1);
      const rewriteHard = homeVerifiedCommentLib.homeVerifiedJudgeHardFail(rewriteJudge, rewritten);
      if (rewriteJudge.passed && rewriteHard.ok) {
        finalReply = rewritten;
        decision = review.decision || "rewrite";
        finalJudge = rewriteJudge;
        hard = rewriteHard;
      } else {
        finalJudge = rewriteJudge.passed === false ? rewriteJudge : finalJudge;
        hard = rewriteHard.ok ? hard : rewriteHard;
        decision = "discard_after_rewrite";
      }
    }

    hard = homeVerifiedCommentLib.homeVerifiedJudgeHardFail(finalJudge, finalReply);
    if (!finalJudge.passed || !hard.ok) {
      const reasonBits = [
        finalJudge.reason || "품질 기준 미달",
        ...(hard.reasons || []),
      ].filter(Boolean).join(" | ");
      const error = new Error(`홈 원글 최종 심사 탈락(discard): ${finalJudge.score ?? "?"}점 - ${reasonBits}`);
      error.code = "HOME_VERIFIED_JUDGE_DISCARD";
      error.discard = true;
      error.hardFailReasons = hard.reasons || [];
      throw error;
    }
    logEvent("terafabx_home_verified_gemini_review_ok", {
      targetUrl: target.url,
      finalReply,
      decision,
      score: finalJudge.score,
      stage1Preferred: decision === "keep_stage1",
      runDir,
    });
    return {
      finalReply,
      decision,
      reason: finalJudge.reason || null,
      score: finalJudge.score,
      finalJudge: {
        ...finalJudge,
        qualityFlagsComplete: finalJudge.qualityFlagsComplete !== false,
      },
      usedGemini: true,
    };
  } catch (error) {
    logEvent("terafabx_home_verified_gemini_review_error", {
      targetUrl: target.url,
      grokReply: grok.reply,
      error: error.message,
      runDir,
    });
    if (TERAFABX_GEMINI_REVIEW_REQUIRED) throw error;
    return {
      finalReply: grok.reply,
      usedGemini: false,
      fallback: true,
      error: error.message,
      finalJudge: { passed: false, score: null, qualityFlagsComplete: false, reason: error.message },
    };
  } finally {
    if (options.cleanupBrowser !== false) {
      const cleanup = await closeTerafabxGeminiHeadlessBrowser({ port: chromePort, profileDir }).catch((err) => ({ error: err.message }));
      logEvent("terafabx_home_verified_gemini_review_cleanup", { targetUrl: target.url, cleanup });
    }
  }
}

/** own-post buildTerafabxPreparedCommentRecord 와 완전 분리된 홈 원글 prepare */
async function buildHomeVerifiedPreparedCommentRecord(target, options = {}) {
  const worker = Math.max(0, Number(options.workerIndex || 0));
  const chromePort = Number(options.chromePort || (TERAFABX_HOME_VERIFIED_COMMENT_GEMINI_PORT_BASE + worker));
  const profileDir = options.profileDir || `${TERAFABX_GEMINI_PROFILE_DIR}-home-verified-${worker + 1}`;
  const contextProvider = resolveHomeVerifiedContextProvider(options);
  // 1단계: 기본 Gemini text-only 문맥+초안 (Grok 쿼타 회피)
  const stage1Context = await analyzeHomeVerifiedContext(target, {
    contextProvider,
    session: options.grokContextSession || `${TERAFABX_GROK_WEB_SESSION}-home-verified-${worker + 1}`,
    skipGrokStateSync: Boolean(options.skipGrokStateSync),
    timeoutMs: options.timeoutMs,
    chromePort,
    profileDir,
    cleanupBrowser: false,
    geminiPriority: options.geminiPriority,
  });
  if (!hasDetailedTerafabxGrokContext(stage1Context) || !stage1Context.reply) {
    throw new Error("홈 원글 검증 문맥/초안이 없어 진행하지 않습니다.");
  }
  assertConfirmedHomeVerifiedContext(stage1Context);
  const draftResult = {
    ...normalizeTerafabxGrokResult({
      reply: stage1Context.reply,
      contextSummary: stage1Context.contextSummary,
      keyPoints: stage1Context.keyPoints,
      rawPreview: stage1Context.rawPreview,
    }),
    provider: `${stage1Context.provider || "gemini-web-context"}+home-verified-draft`,
    mode: "home_verified_original",
    pipeline: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
  };
  logEvent("terafabx_home_verified_stage1_draft_ready", {
    targetUrl: target.url,
    reply: draftResult.reply,
    contextPreview: draftResult.contextSummary.slice(0, 240),
    contextProvider: stage1Context.provider,
    pipeline: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
  });
  // 2단계: Gemini 검수+judge (같은 headless 브라우저 재사용)
  const geminiReview = await reviewHomeVerifiedReplyWithGemini(target, draftResult, {
    chromePort,
    profileDir,
    geminiPriority: options.geminiPriority,
    cleanupBrowser: options.cleanupBrowser !== false,
    groundingContext: stage1Context,
  });
  assertTerafabxReplyReviewScoreQualified(geminiReview, TERAFABX_REVIEW_COMMENT_MIN_SCORE);
  // stage1 초안 우선. 길이 trim/톤 polish 하지 않음.
  const comment = validateTerafabxReply(geminiReview.finalReply || draftResult.reply);
  const generator = [
    stage1Context.provider || "gemini-web-context",
    "home-verified-stage1-draft",
    geminiReview.decision === "keep_stage1" ? "stage1-kept" : "stage1-rewrite-fallback",
    geminiReview.usedGemini ? "home-verified-gemini-judge" : "home-verified-gemini-skipped",
  ].join("+");
  return {
    at: new Date().toISOString(),
    targetUrl: target.url,
    targetId: target.targetId,
    targetText: target.targetText,
    authorHandle: target.authorHandle || null,
    rootPostUrl: null,
    rootPostText: null,
    comment,
    grokComment: draftResult.reply,
    grokContext: terafabxGrokContextForRecord({
      ...draftResult,
      provider: stage1Context.provider,
    }),
    geminiReview: {
      used: Boolean(geminiReview.usedGemini),
      score: geminiReview.score ?? null,
      decision: geminiReview.decision || null,
      reason: geminiReview.reason || null,
      fallback: Boolean(geminiReview.fallback),
      error: geminiReview.error || null,
      finalJudge: geminiReview.finalJudge || null,
    },
    replyUrl: null,
    generator,
    contextProvider: stage1Context.provider,
    manual: Boolean(options.manual),
    source: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
    kind: "home_verified_original",
  };
}

async function prepareTerafabxHomeVerifiedComment(post, options = {}) {
  const contextProvider = resolveHomeVerifiedContextProvider(options);
  // Gemini text-only 1단계는 Grok 쿼타와 무관. Grok 폴백일 때만 한도 적용.
  if (contextProvider !== "gemini") {
    const quota = homeVerifiedCommentLib.homeVerifiedGrokQuotaDisposition(loadTerafabxState());
    if (!quota.allowGenerate) {
      const error = new Error(quota.message || "Grok 사용량 제한");
      error.code = "GROK_QUOTA";
      error.backoffUntil = quota.until;
      throw error;
    }
  }
  // backlog에 이미 들어 있어도 욕설·비난·논란 원글은 prepare 전 재차단
  const contentSafety = homeVerifiedCommentLib.assessHomeVerifiedOriginalContentSafety(
    post?.text || post?.targetText || "",
    { bannedRe: TERAFABX_COMMENT_TARGET_BANNED_RE },
  );
  if (!contentSafety.ok) {
    const error = new Error(`원글 제외: ${contentSafety.reason}`);
    error.code = "UNSAFE_ORIGINAL";
    error.reason = contentSafety.reason;
    throw error;
  }
  const target = buildTerafabxHomeVerifiedCommentTarget(post);
  const authorCap = homeVerifiedCommentLib.authorDailyUsageFromHistory({
    history: loadTerafabxState().homeVerifiedCommentHistory,
    pending: loadTerafabxHomeVerifiedWriteQueue(),
    authorHandle: target.authorHandle,
    formatKstDateKey,
    limit: TERAFABX_HOME_VERIFIED_COMMENT_AUTHOR_DAILY_LIMIT,
  });
  if (!authorCap.allowed) {
    const error = new Error(`작성자 일일 한도: @${authorCap.handle} ${authorCap.total}/${authorCap.limit}`);
    error.code = "AUTHOR_DAILY_CAP";
    throw error;
  }
  const worker = Math.max(0, Number(options.workerIndex || 0));
  const prepared = await buildHomeVerifiedPreparedCommentRecord(target, {
    manual: Boolean(options.manual),
    workerIndex: worker,
    chromePort: TERAFABX_HOME_VERIFIED_COMMENT_GEMINI_PORT_BASE + worker,
    profileDir: `${TERAFABX_GEMINI_PROFILE_DIR}-home-verified-${worker + 1}`,
    grokContextSession: options.grokContextSession || `${TERAFABX_GROK_WEB_SESSION}-home-verified-${worker + 1}`,
    contextProvider,
  });
  const quality = assessTerafabxHomeVerifiedWriteQuality({
    prepared,
    target,
    source: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
  });
  if (!quality.ok) {
    const error = new Error(`품질 게이트 탈락: ${(quality.errors || []).join(", ")}`);
    error.code = "QUALITY_GATE";
    error.quality = quality;
    throw error;
  }
  return { target, prepared, quality };
}

function enqueueTerafabxHomeVerifiedWriteRecord({ target, prepared, manual = false } = {}) {
  const record = persistTerafabxHomeVerifiedWrite({
    target,
    prepared,
    targetUrl: target.url,
    rootUrl: target.rootPostUrl || target.url,
    authorHandle: target.authorHandle,
    status: "queued",
    stage: "pending_post",
    source: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
    manual: Boolean(manual),
    queuedAt: new Date().toISOString(),
  });
  pumpTerafabxHomeVerifiedWriteQueue();
  return record;
}

function saveTerafabxHomeVerifiedCommentSuccess(record, posted) {
  const state = loadTerafabxState();
  const now = new Date().toISOString();
  const historyRecord = {
    at: now,
    targetUrl: record.targetUrl,
    authorHandle: record.authorHandle || record?.target?.authorHandle || "",
    comment: record.prepared?.comment,
    replyUrl: posted?.replyUrl || null,
    source: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
    generator: record.prepared?.generator || null,
  };
  const id = parseXStatusUrl(record.targetUrl)?.id;
  saveTerafabxState({
    homeVerifiedCommentHistory: [historyRecord, ...(state.homeVerifiedCommentHistory || [])].slice(0, 500),
    homeVerifiedCommentSeenIds: id
      ? Array.from(new Set([id, ...(state.homeVerifiedCommentSeenIds || [])])).slice(0, 5000)
      : state.homeVerifiedCommentSeenIds,
    commentHistory: [historyRecord, ...(state.commentHistory || [])].slice(0, TERAFABX_COMMENT_HISTORY_LIMIT),
    lastCommentRunAt: now,
    lastCommentStatus: "ok",
    lastCommentError: null,
    lastComment: record.prepared?.comment,
    lastCommentTarget: record.targetUrl,
    lastReplyUrl: posted?.replyUrl || null,
  });
  removeTerafabxHomeVerifiedWrite(record.id);
  return historyRecord;
}

async function postTerafabxHomeVerifiedWriteRecord(record) {
  const latest = persistTerafabxHomeVerifiedWrite({
    ...record,
    status: "posting",
    attempts: Math.max(0, Number(record.attempts || 0)) + 1,
    lastAttemptAt: new Date().toISOString(),
  });
  if (terafabxHomeVerifiedAlreadyHandled(loadTerafabxState(), latest.targetUrl)
    && (loadTerafabxState().homeVerifiedCommentHistory || []).some((item) => parseXStatusUrl(item.targetUrl)?.id === parseXStatusUrl(latest.targetUrl)?.id)) {
    removeTerafabxHomeVerifiedWrite(latest.id);
    return { status: "already_posted", targetUrl: latest.targetUrl };
  }
  const quality = assessTerafabxHomeVerifiedWriteQuality(latest);
  if (!quality.ok) {
    removeTerafabxHomeVerifiedWrite(latest.id);
    logEvent("terafabx_home_verified_write_quality_rejected", {
      id: latest.id,
      targetUrl: latest.targetUrl,
      errors: quality.errors,
    });
    return { status: "quality_rejected", quality, record: latest };
  }
  const state = loadTerafabxState();
  if (state.homeVerifiedCommentPrefillOnly) {
    return {
      status: "prefill_only",
      record: persistTerafabxHomeVerifiedWrite({
        ...latest,
        status: "queued",
        stage: "pending_post",
        lastError: "prefill_only: 실제 게시 비활성",
      }),
    };
  }
  const daily = homeVerifiedCommentLib.homeVerifiedDailyProgress({
    history: state.homeVerifiedCommentHistory,
    pending: [],
    dailyTarget: TERAFABX_HOME_VERIFIED_COMMENT_DAILY_TARGET,
    formatKstDateKey,
  });
  if (daily.atCap) {
    return {
      status: "held",
      record: persistTerafabxHomeVerifiedWrite({
        ...latest,
        status: "queued",
        stage: "held",
        retryAt: nextKstDateBoundary().toISOString(),
        lastError: `daily_target_reached:${daily.postedToday}/${daily.dailyTarget}`,
      }),
    };
  }
  const authorCap = homeVerifiedCommentLib.authorDailyUsageFromHistory({
    history: state.homeVerifiedCommentHistory,
    pending: loadTerafabxHomeVerifiedWriteQueue().filter((row) => row.id !== latest.id),
    authorHandle: latest.authorHandle,
    formatKstDateKey,
    limit: TERAFABX_HOME_VERIFIED_COMMENT_AUTHOR_DAILY_LIMIT,
  });
  if (!authorCap.allowed) {
    return {
      status: "held",
      record: persistTerafabxHomeVerifiedWrite({
        ...latest,
        status: "queued",
        stage: "held",
        retryAt: nextKstDateBoundary().toISOString(),
        lastError: authorCap.reason,
      }),
    };
  }
  // 일 300 페이스: 최소 게시 간격 (manual post_one 은 짧게)
  const desiredGapMs = latest.manual
    ? Math.min(30_000, TERAFABX_HOME_VERIFIED_COMMENT_MIN_POST_GAP_MS)
    : TERAFABX_HOME_VERIFIED_COMMENT_MIN_POST_GAP_MS;
  const delayMs = terafabxOwnPostReplyWriterDelayMs({
    lastCompletedAtMs: terafabxHomeVerifiedCommentXWriterLastCompletedAtMs,
    desiredGapMs,
  });
  if (delayMs > 0) await sleep(delayMs);
  try {
    const posted = await postTerafabxReply(latest.targetUrl, latest.prepared.comment, {
      headless: true,
      xResourceKind: "homeVerified",
      lockAction: "home-verified-comment-writer",
      cleanupHeadless: true,
      verifyRelationship: true,
    });
    if (!posted?.ok || !posted.replyUrl) {
      const uncertain = persistTerafabxHomeVerifiedWrite({
        ...latest,
        status: "queued",
        stage: "verification_required",
        lastError: "게시 결과 불확실 — 재게시 금지",
      });
      return { status: "verification_required", record: uncertain };
    }
    const history = saveTerafabxHomeVerifiedCommentSuccess(latest, posted);
    terafabxHomeVerifiedCommentXWriterLastCompletedAtMs = Date.now();
    logEvent("terafabx_home_verified_comment_posted", {
      targetUrl: latest.targetUrl,
      replyUrl: posted.replyUrl,
      comment: latest.prepared.comment,
    });
    return { status: "posted", history, posted };
  } catch (error) {
    if (isTerafabxReplySubmissionUncertain(error) || error?.code === "TERAFABX_REPLY_SUBMISSION_UNCERTAIN") {
      const uncertain = persistTerafabxHomeVerifiedWrite({
        ...latest,
        status: "queued",
        stage: "verification_required",
        lastError: error.message,
      });
      return { status: "verification_required", record: uncertain, error: error.message };
    }
    if (isTerafabxXRateLimitError(error)) {
      const retryAt = new Date(Date.now() + TERAFABX_X_GLOBAL_BACKOFF_MS).toISOString();
      saveTerafabxState({
        homeVerifiedCommentXWriteBackoffUntil: retryAt,
        homeVerifiedCommentXWriteBackoffError: error.message,
        xGlobalBackoffUntil: retryAt,
        xGlobalBackoffError: error.message,
        xGlobalBackoffSource: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
      });
      return {
        status: "backoff",
        record: persistTerafabxHomeVerifiedWrite({
          ...latest,
          status: "queued",
          stage: "pending_post",
          retryAt,
          lastError: error.message,
        }),
      };
    }
    // 재발 방지: 삭제/제한/target-not-found 는 재시도 루프에 넣지 않고 영구 폐기
    const maxAttempts = Math.max(1, Number(process.env.TERAFABX_HOME_VERIFIED_MAX_POST_ATTEMPTS || 5));
    const disposition = homeVerifiedCommentLib.homeVerifiedPostFailureDisposition(error, {
      attempts: latest.attempts,
      maxAttempts,
    });
    if (disposition.discard) {
      markTerafabxHomeVerifiedTargetDiscarded(latest.targetUrl, {
        reason: disposition.reason,
        error: error.message,
        attempts: latest.attempts,
      });
      removeTerafabxHomeVerifiedWrite(latest.id);
      logEvent("terafabx_home_verified_dead_target_discarded", {
        id: latest.id,
        targetUrl: latest.targetUrl,
        authorHandle: latest.authorHandle,
        reason: disposition.reason,
        attempts: latest.attempts,
        error: String(error.message || "").slice(0, 400),
      });
      return {
        status: "discarded_dead_target",
        reason: disposition.reason,
        error: error.message,
        targetUrl: latest.targetUrl,
      };
    }
    const failed = persistTerafabxHomeVerifiedWrite({
      ...latest,
      status: "queued",
      stage: "pending_post",
      lastError: error.message,
      retryAt: new Date(Date.now() + 10 * 60 * 1000).toISOString(),
    });
    return { status: "retry", record: failed, error: error.message };
  }
}

function recoverStuckHomeVerifiedPostingRows(nowMs = Date.now()) {
  const stuckMs = Math.max(120_000, Number(process.env.TERAFABX_HOME_VERIFIED_POSTING_STUCK_MS || 8 * 60 * 1000));
  const rows = loadTerafabxHomeVerifiedWriteQueue();
  let recovered = 0;
  for (const row of rows) {
    if (String(row.status) !== "posting") continue;
    // 현재 프로세스 큐에 아직 실행 중이면 건드리지 않음
    if (terafabxHomeVerifiedCommentWriteQueuedIds.has(row.id)) continue;
    const started = Date.parse(row.lastAttemptAt || row.queuedAt || 0);
    if (!Number.isFinite(started) || (nowMs - started) < stuckMs) continue;
    persistTerafabxHomeVerifiedWrite({
      ...row,
      status: "queued",
      stage: "pending_post",
      lastError: `recovered_stuck_posting:${Math.round((nowMs - started) / 1000)}s`,
      retryAt: null,
    });
    recovered += 1;
    logEvent("terafabx_home_verified_stuck_posting_recovered", {
      id: row.id,
      targetUrl: row.targetUrl,
      stuckMs: nowMs - started,
    });
  }
  return recovered;
}

function pumpTerafabxHomeVerifiedWriteQueue() {
  const state = loadTerafabxState();
  if (state.homeVerifiedCommentPrefillOnly) {
    return { pumped: 0, reason: "prefill_only" };
  }
  if (!state.homeVerifiedCommentEnabled && !loadTerafabxHomeVerifiedWriteQueue().some((row) => row.manual)) {
    return { pumped: 0, reason: "disabled" };
  }
  const recoveredStuck = recoverStuckHomeVerifiedPostingRows();
  const rows = loadTerafabxHomeVerifiedWriteQueue().filter((row) => {
    if (row.stage === "verification_required") return false;
    if (row.stage === "held") {
      const retryAt = Date.parse(row.retryAt || "");
      return Number.isFinite(retryAt) && retryAt <= Date.now();
    }
    const retryAt = Date.parse(row.retryAt || "");
    if (Number.isFinite(retryAt) && retryAt > Date.now()) return false;
    return row.status === "queued" || row.status === "posting";
  });
  let pumped = 0;
  for (const row of rows) {
    if (terafabxHomeVerifiedCommentWriteQueuedIds.has(row.id)) continue;
    // 동시 게시는 1건만 (헤드리스 세션/락 경합 방지) — 일 300 페이스는 갭으로 조절
    if (pumped >= 1) break;
    terafabxHomeVerifiedCommentWriteQueuedIds.add(row.id);
    pumped += 1;
    terafabxHomeVerifiedCommentXWriterQueue.enqueue(async () => {
      try {
        await postTerafabxHomeVerifiedWriteRecord(row);
      } finally {
        terafabxHomeVerifiedCommentWriteQueuedIds.delete(row.id);
      }
    }).catch((error) => {
      logEvent("terafabx_home_verified_write_queue_error", { id: row.id, error: error.message });
      terafabxHomeVerifiedCommentWriteQueuedIds.delete(row.id);
      // 예외 시 posting 잔류 방지
      try {
        const fresh = loadTerafabxHomeVerifiedWriteQueue().find((item) => item.id === row.id);
        if (fresh && String(fresh.status) === "posting") {
          persistTerafabxHomeVerifiedWrite({
            ...fresh,
            status: "queued",
            stage: "pending_post",
            lastError: error.message,
            retryAt: new Date(Date.now() + 60_000).toISOString(),
          });
        }
      } catch {}
    });
  }
  return { pumped, recoveredStuck, durable: loadTerafabxHomeVerifiedWriteQueue().length };
}

async function runTerafabxHomeVerifiedCommentPrepareCycle(options = {}) {
  if (terafabxHomeVerifiedCommentBusy) return { ok: false, skipped: "busy" };
  terafabxHomeVerifiedCommentBusy = true;
  const startedAt = new Date().toISOString();
  try {
    // Gemini text-only 기본 경로에서는 Grok 쿼타로 prepare를 막지 않음
    const contextProvider = resolveHomeVerifiedContextProvider(options);
    if (contextProvider !== "gemini") {
      const quota = homeVerifiedCommentLib.homeVerifiedGrokQuotaDisposition(loadTerafabxState());
      if (!quota.allowGenerate) {
        saveTerafabxState({
          homeVerifiedCommentLastRunAt: startedAt,
          homeVerifiedCommentLastStatus: "blocked",
          homeVerifiedCommentLastError: quota.message,
        });
        return { ok: false, skipped: "grok_quota", error: quota.message, until: quota.until };
      }
    }

    let state = loadTerafabxState();
    if (Array.isArray(options.candidates) && options.candidates.length) {
      ingestTerafabxHomeVerifiedCandidates(options.candidates, { limit: options.limit });
      state = loadTerafabxState();
    }

    const limit = Math.max(1, Number(options.limit || TERAFABX_HOME_VERIFIED_COMMENT_BATCH_LIMIT));
    const backlog = homeVerifiedCommentLib.normalizeHomeVerifiedCandidateBacklog(
      state.homeVerifiedCommentBacklog,
      homeVerifiedCommentHelpers(),
    );
    const batch = backlog.slice(0, limit);
    const results = { prepared: 0, failed: 0, discarded: 0, held: 0, errors: [], items: [] };

    for (let index = 0; index < batch.length; index += 1) {
      const post = batch[index];
      try {
        if (terafabxHomeVerifiedAlreadyHandled(loadTerafabxState(), post.url)) {
          results.held += 1;
          continue;
        }
        let candidate = post;
        try {
          const live = await enrichHomeVerifiedCandidateFromApi(post.url);
          if (!live.ok) {
            results.held += 1;
            results.errors.push({ url: post.url, reasons: live.reasons });
            continue;
          }
          candidate = live.post;
        } catch (apiError) {
          logEvent("terafabx_home_verified_metadata_error", { url: post.url, error: apiError.message });
        }
        // prepare 직전 재분류 (P0 필터 — 실패 초안을 큐에 넣지 않음)
        const reclass = classifyTerafabxHomeVerifiedOriginalCandidate(candidate);
        if (!reclass.ok) {
          results.held += 1;
          results.errors.push({ url: post.url, reasons: reclass.reasons, discarded: true });
          continue;
        }
        const { target, prepared } = await prepareTerafabxHomeVerifiedComment(reclass.post, {
          workerIndex: index % Math.max(1, terafabxBrowserConcurrency(5)),
          manual: Boolean(options.manual),
        });
        const queued = enqueueTerafabxHomeVerifiedWriteRecord({
          target,
          prepared,
          manual: Boolean(options.manual),
        });
        results.prepared += 1;
        results.items.push({
          targetUrl: target.url,
          comment: prepared.comment,
          id: queued.id,
          decision: prepared.geminiReview?.decision || null,
        });
      } catch (error) {
        results.failed += 1;
        const discarded = Boolean(error.discard || error.code === "HOME_VERIFIED_JUDGE_DISCARD");
        if (discarded) results.discarded = (results.discarded || 0) + 1;
        results.errors.push({
          url: post.url,
          error: error.message,
          code: error.code || null,
          discarded,
          hardFailReasons: error.hardFailReasons || null,
        });
        logEvent("terafabx_home_verified_prepare_item_failed", {
          url: post.url,
          code: error.code || null,
          discarded,
          error: error.message,
        });
        if (error.code === "GROK_QUOTA") {
          const until = error.backoffUntil || parseTerafabxGrokQuotaResetAt(error.message);
          saveTerafabxState({
            grokQuotaBackoffUntil: until,
            grokQuotaMessage: error.message,
          });
          break;
        }
      }
    }

    const remainingBacklog = backlog.filter((item) => !batch.some((b) => b.id === item.id));
    const preparedIds = new Set(results.items.map((item) => parseXStatusUrl(item.targetUrl)?.id).filter(Boolean));
    saveTerafabxState({
      homeVerifiedCommentBacklog: remainingBacklog.filter((item) => !preparedIds.has(item.id)),
      homeVerifiedCommentLastRunAt: startedAt,
      homeVerifiedCommentLastStatus: results.prepared > 0 ? "ok" : (results.failed ? "error" : "idle"),
      homeVerifiedCommentLastError: results.errors[0]?.error || null,
      homeVerifiedCommentLastSummary: {
        at: startedAt,
        prepared: results.prepared,
        failed: results.failed,
        discarded: results.discarded || 0,
        held: results.held,
        pending: loadTerafabxHomeVerifiedWriteQueue().length,
        prefillOnly: Boolean(loadTerafabxState().homeVerifiedCommentPrefillOnly),
      },
    });
    logEvent("terafabx_home_verified_prepare_cycle", results);
    return { ok: true, ...results };
  } catch (error) {
    saveTerafabxState({
      homeVerifiedCommentLastRunAt: startedAt,
      homeVerifiedCommentLastStatus: "error",
      homeVerifiedCommentLastError: error.message,
    });
    logEvent("terafabx_home_verified_prepare_error", { error: error.message });
    throw error;
  } finally {
    terafabxHomeVerifiedCommentBusy = false;
  }
}

async function maybeRunTerafabxHomeVerifiedCommentAutomation() {
  if (terafabxHomeVerifiedCommentSchedulerBusy || terafabxHomeVerifiedCommentBusy) return { skipped: "busy" };
  const state = loadTerafabxState();
  if (!state.homeVerifiedCommentEnabled) return { skipped: "disabled" };
  const lastMs = Date.parse(state.homeVerifiedCommentLastRunAt || "") || 0;
  if (Date.now() - lastMs < TERAFABX_HOME_VERIFIED_COMMENT_INTERVAL_MS) return { skipped: "interval" };
  terafabxHomeVerifiedCommentSchedulerBusy = true;
  try {
    const pendingRows = loadTerafabxHomeVerifiedWriteQueue();
    const daily = homeVerifiedCommentLib.homeVerifiedDailyProgress({
      history: state.homeVerifiedCommentHistory,
      pending: pendingRows,
      dailyTarget: TERAFABX_HOME_VERIFIED_COMMENT_DAILY_TARGET,
      formatKstDateKey,
    });
    if (daily.atCap) {
      logEvent("terafabx_home_verified_daily_target_reached", daily);
      return { skipped: "daily_target_reached", daily };
    }

    // live 모드면 게시 큐 드레인 (일 목표 잔량 있을 때만)
    const pump = state.homeVerifiedCommentPrefillOnly
      ? { pumped: 0, reason: "prefill_only" }
      : pumpTerafabxHomeVerifiedWriteQueue();

    const pendingCount = loadTerafabxHomeVerifiedWriteQueue().length;
    const needPrepare = daily.remainingAfterPending > 0
      && pendingCount < TERAFABX_HOME_VERIFIED_COMMENT_READY_BUFFER;

    let backlogCount = homeVerifiedCommentLib.normalizeHomeVerifiedCandidateBacklog(
      loadTerafabxState().homeVerifiedCommentBacklog,
      homeVerifiedCommentHelpers(),
    ).length;

    // 게시 전 정책 하드페일 초안 청소 (라이브 품질 피드백)
    const purge = purgeHomeVerifiedPolicyFailPending({ sample: 12 });
    if (purge.purged > 0) {
      logEvent("terafabx_home_verified_auto_policy_purge", purge);
    }
    // 삭제/제한 타겟 재시도 루프 청소
    const deadPurge = purgeHomeVerifiedDeadTargetPending({ sample: 12 });
    if (deadPurge.purged > 0) {
      logEvent("terafabx_home_verified_auto_dead_target_purge", deadPurge);
    }

    // following 합성 discover: 백로그/버퍼 부족 시 공격적으로 보충
    const needDiscover = needPrepare
      && (
        backlogCount < Math.max(TERAFABX_HOME_VERIFIED_COMMENT_BATCH_LIMIT, 8)
        || pendingCount < Math.floor(TERAFABX_HOME_VERIFIED_COMMENT_READY_BUFFER * 0.6)
      );
    let lastDiscover = null;
    if (needDiscover) {
      try {
        lastDiscover = await discoverTerafabxHomeVerifiedCandidates({
          source: TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE,
          limit: TERAFABX_HOME_VERIFIED_COMMENT_DISCOVER_LIMIT,
          maxCheck: Math.max(
            TERAFABX_HOME_VERIFIED_COMMENT_DISCOVER_LIMIT * 2,
            160,
          ),
          batchSize: 40,
          concurrency: 5,
        });
        backlogCount = homeVerifiedCommentLib.normalizeHomeVerifiedCandidateBacklog(
          loadTerafabxState().homeVerifiedCommentBacklog,
          homeVerifiedCommentHelpers(),
        ).length;
      } catch (error) {
        logEvent("terafabx_home_verified_auto_discover_error", { error: error.message });
      }
    }

    if (needPrepare && backlogCount > 0) {
      const prepareLimit = Math.min(
        TERAFABX_HOME_VERIFIED_COMMENT_BATCH_LIMIT,
        daily.remainingAfterPending,
        Math.max(1, TERAFABX_HOME_VERIFIED_COMMENT_READY_BUFFER - pendingCount),
      );
      const prepared = await runTerafabxHomeVerifiedCommentPrepareCycle({
        manual: false,
        limit: prepareLimit,
      });
      return {
        ok: true,
        pump,
        purge,
        daily,
        prepareLimit,
        discover: lastDiscover ? {
          selected: lastDiscover.personalSelected,
          rejected: lastDiscover.rejected,
          skippedDuplicateAuthor: lastDiscover.skippedDuplicateAuthor,
          rejectReasonCounts: lastDiscover.rejectReasonCounts,
          yieldRate: lastDiscover.yieldRate,
        } : null,
        source: TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE,
        ...prepared,
      };
    }
    return {
      skipped: needPrepare ? "empty_backlog" : "buffer_full_or_target_met",
      pump,
      purge,
      daily,
      pendingCount,
      backlogCount,
      discover: lastDiscover ? {
        selected: lastDiscover.personalSelected,
        rejected: lastDiscover.rejected,
        skippedDuplicateAuthor: lastDiscover.skippedDuplicateAuthor,
        rejectReasonCounts: lastDiscover.rejectReasonCounts,
        yieldRate: lastDiscover.yieldRate,
      } : null,
      source: TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE,
    };
  } finally {
    terafabxHomeVerifiedCommentSchedulerBusy = false;
  }
}

function getTerafabxHomeVerifiedCommentStatus(state = loadTerafabxState()) {
  const pending = loadTerafabxHomeVerifiedWriteQueue();
  const backlog = homeVerifiedCommentLib.normalizeHomeVerifiedCandidateBacklog(
    state.homeVerifiedCommentBacklog,
    homeVerifiedCommentHelpers(),
  );
  const contextProvider = resolveHomeVerifiedContextProvider();
  // Gemini text-only 기본 경로에서는 Grok 쿼타가 생성을 막지 않음.
  const grokQuotaRaw = homeVerifiedCommentLib.homeVerifiedGrokQuotaDisposition(state);
  const grokQuota = contextProvider === "gemini"
    ? { ...grokQuotaRaw, allowGenerate: true, message: grokQuotaRaw.allowGenerate ? null : `Grok 한도(미사용: context=${contextProvider})` }
    : grokQuotaRaw;
  const daily = homeVerifiedCommentLib.homeVerifiedDailyProgress({
    history: state.homeVerifiedCommentHistory,
    pending,
    dailyTarget: TERAFABX_HOME_VERIFIED_COMMENT_DAILY_TARGET,
    formatKstDateKey,
  });
  const pipeline = homeVerifiedCommentLib.homeVerifiedPipelineStatus({
    enabled: Boolean(state.homeVerifiedCommentEnabled),
    prefillOnly: state.homeVerifiedCommentPrefillOnly !== false,
    backlogCount: backlog.length,
    pendingCount: pending.length,
    postedToday: daily.postedToday,
    dailyTarget: daily.dailyTarget,
    grokQuota,
    lastError: state.homeVerifiedCommentLastError,
  });
  return {
    ...pipeline,
    contextProvider,
    discoverSource: TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE,
    daily,
    enabled: Boolean(state.homeVerifiedCommentEnabled),
    prefillOnly: state.homeVerifiedCommentPrefillOnly !== false,
    busy: terafabxHomeVerifiedCommentBusy,
    schedulerBusy: terafabxHomeVerifiedCommentSchedulerBusy,
    intervalMs: TERAFABX_HOME_VERIFIED_COMMENT_INTERVAL_MS,
    batchLimit: TERAFABX_HOME_VERIFIED_COMMENT_BATCH_LIMIT,
    authorDailyLimit: TERAFABX_HOME_VERIFIED_COMMENT_AUTHOR_DAILY_LIMIT,
    dailyTarget: TERAFABX_HOME_VERIFIED_COMMENT_DAILY_TARGET,
    readyBuffer: TERAFABX_HOME_VERIFIED_COMMENT_READY_BUFFER,
    discoverLimit: TERAFABX_HOME_VERIFIED_COMMENT_DISCOVER_LIMIT,
    minPostGapMs: TERAFABX_HOME_VERIFIED_COMMENT_MIN_POST_GAP_MS,
    backlogCount: backlog.length,
    pendingCount: pending.length,
    postedToday: daily.postedToday,
    pending: pending.slice(0, 20).map((row) => ({
      id: row.id,
      targetUrl: row.targetUrl,
      authorHandle: row.authorHandle,
      stage: row.stage,
      status: row.status,
      comment: row.prepared?.comment || "",
      lastError: row.lastError,
      retryAt: row.retryAt,
      queuedAt: row.queuedAt,
    })),
    backlog: backlog.slice(0, 20),
    history: (state.homeVerifiedCommentHistory || []).slice(0, 10),
    writerPort: TERAFABX_HOME_VERIFIED_COMMENT_X_PORT,
    durableQueuePath: TERAFABX_HOME_VERIFIED_COMMENT_WRITE_QUEUE_PATH,
    lastRunAt: state.homeVerifiedCommentLastRunAt,
    lastStatus: state.homeVerifiedCommentLastStatus,
    lastError: state.homeVerifiedCommentLastError,
    lastSummary: state.homeVerifiedCommentLastSummary,
    grokQuota,
    lastDiscoveryAt: state.homeVerifiedCommentLastDiscoveryAt || null,
    lastDiscovery: state.homeVerifiedCommentLastDiscoverySummary || null,
    lastDeadTargetDiscard: state.homeVerifiedCommentLastDeadTargetDiscard || null,
    source: TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
    policy: {
      homeTimelineOriginalOnly: true,
      blueVerifiedOnly: true,
      personalBlueVerifiedOnly: true,
      allowedVerificationTypes: ["individual", "blue"],
      excludeOrganizationGovernmentBusiness: true,
      excludeReplies: true,
      excludeRetweets: true,
      excludeQuotes: true,
      excludeProfanityAttackControversy: true,
      excludeSensitiveBannedTopics: true,
      contextProvider: TERAFABX_HOME_VERIFIED_CONTEXT_PROVIDER || "gemini",
      geminiTextOnlyContextAndDraft: TERAFABX_HOME_VERIFIED_CONTEXT_PROVIDER !== "web"
        && TERAFABX_HOME_VERIFIED_CONTEXT_PROVIDER !== "cli",
      grokContextAndDraft: TERAFABX_HOME_VERIFIED_CONTEXT_PROVIDER === "web"
        || TERAFABX_HOME_VERIFIED_CONTEXT_PROVIDER === "cli",
      geminiReviewAndJudge: true,
      lengthTonePolish: false,
      preferStage1Draft: true,
      draftQualityViaLlmAndPromptOnly: true,
      noDeterministicDraftPolish: true,
      noPostWithoutContext: true,
      discoverSource: TERAFABX_HOME_VERIFIED_DISCOVER_SOURCE,
      dailyTarget: TERAFABX_HOME_VERIFIED_COMMENT_DAILY_TARGET,
      followingSynthesisForDailyTarget: true,
      isolatedFromOps: true,
      independentFromOwnPostReply: true,
      ownPrompts: true,
      sharedOwnPostPrepare: false,
      tone: "gwajeuplupi_casual_reply_not_news_summary",
    },
  };
}

function buildHomeVerifiedDashboardData(requestUrl = "/api/discovery/home-verified-dashboard") {
  const parsedUrl = new URL(requestUrl, "http://localhost");
  const requested = String(parsedUrl.searchParams.get("date") || "").trim();
  const date = requested === "all" || /^\d{4}-\d{2}-\d{2}$/.test(requested)
    ? requested
    : formatKstDateKey();
  const state = loadTerafabxState();
  const status = getTerafabxHomeVerifiedCommentStatus(state);
  const history = (state.homeVerifiedCommentHistory || []).map((item) => ({
    at: item.at || null,
    date: item.at ? formatKstDateKey(item.at) : "",
    targetUrl: item.targetUrl || item.url || "",
    replyUrl: item.replyUrl || null,
    authorHandle: item.authorHandle || "",
    comment: item.comment || "",
    source: item.source || TERAFABX_HOME_VERIFIED_COMMENT_SOURCE,
    generator: item.generator || null,
    manual: item.manual === true,
  }));
  const availableDates = [...new Set(history.map((item) => item.date).filter(Boolean))]
    .sort((left, right) => right.localeCompare(left));
  const timeline = (date === "all" ? history : history.filter((item) => item.date === date))
    .slice(0, 250);
  const pending = loadTerafabxHomeVerifiedWriteQueue().map((row) => ({
    id: row.id,
    at: row.queuedAt || row.lastAttemptAt || null,
    date: formatKstDateKey(row.queuedAt || row.lastAttemptAt || Date.now()),
    targetUrl: row.targetUrl,
    authorHandle: row.authorHandle,
    comment: row.prepared?.comment || "",
    stage: row.stage,
    status: row.status,
    lastError: row.lastError || null,
    retryAt: row.retryAt || null,
    attempts: row.attempts || 0,
  }));
  return {
    ok: true,
    view: "home-verified",
    date,
    availableDates,
    status,
    terafabx: { homeVerifiedComment: status },
    timeline,
    pending,
    lastDiscoveryAt: state.homeVerifiedCommentLastDiscoveryAt || null,
    lastDiscovery: state.homeVerifiedCommentLastDiscoverySummary || null,
    lastDeadTargetDiscard: state.homeVerifiedCommentLastDeadTargetDiscard || null,
    summary: {
      postedToday: status.postedToday,
      pendingCount: status.pendingCount,
      backlogCount: status.backlogCount,
      dailyTarget: status.dailyTarget,
      enabled: status.enabled,
    },
    rows: [],
  };
}

function kstHour(date = new Date()) {
  const value = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Seoul",
    hour: "2-digit",
    hourCycle: "h23",
  }).format(date);
  return Number(value);
}

function isTerafabxQuietPostingTime(date = new Date()) {
  const start = TERAFABX_QUIET_POSTING_START_HOUR;
  const end = TERAFABX_QUIET_POSTING_END_HOUR;
  const hour = kstHour(date);
  if (!Number.isFinite(hour) || start === end) return false;
  return start < end ? hour >= start && hour < end : hour >= start || hour < end;
}

function terafabxDailyCommentProgress(state = loadTerafabxState(), nowValue = new Date(), options = {}) {
  const now = nowValue instanceof Date ? nowValue : new Date(nowValue || Date.now());
  const dailyTarget = Math.max(0, Number(options.dailyTarget ?? TERAFABX_COMMENT_DAILY_TARGET));
  const parts = Object.fromEntries(new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Seoul",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(now).map((part) => [part.type, part.value]));
  const minuteOfDay = (Number(parts.hour) * 60) + Number(parts.minute) + (Number(parts.second) / 60);
  const quietStart = TERAFABX_QUIET_POSTING_START_HOUR;
  const quietEnd = TERAFABX_QUIET_POSTING_END_HOUR;
  const isActiveHour = (hour) => {
    if (quietStart === quietEnd) return true;
    const quiet = quietStart < quietEnd
      ? hour >= quietStart && hour < quietEnd
      : hour >= quietStart || hour < quietEnd;
    return !quiet;
  };
  let activeMinutesTotal = 0;
  let activeMinutesElapsed = 0;
  for (let hour = 0; hour < 24; hour += 1) {
    if (!isActiveHour(hour)) continue;
    activeMinutesTotal += 60;
    activeMinutesElapsed += Math.max(0, Math.min(60, minuteOfDay - (hour * 60)));
  }
  const todayKey = formatKstDateKey(now);
  const postedKeys = new Set();
  for (const record of state?.commentHistory || []) {
    const time = record?.postedAt || record?.at;
    if (!record?.replyUrl || !time || formatKstDateKey(time) !== todayKey) continue;
    postedKeys.add(String(record.replyUrl || record.targetUrl || `${time}:${record.comment || ""}`));
  }
  const postedToday = postedKeys.size;
  const remaining = Math.max(0, dailyTarget - postedToday);
  const targetByNow = activeMinutesTotal > 0
    ? Math.min(dailyTarget, Math.floor((activeMinutesElapsed / activeMinutesTotal) * dailyTarget))
    : dailyTarget;
  const activeMinutesRemaining = Math.max(0, activeMinutesTotal - activeMinutesElapsed);
  const baseIntervalMs = dailyTarget > 0
    ? Math.max(TERAFABX_COMMENT_MIN_INTERVAL_MS, Math.floor((activeMinutesTotal * 60 * 1000) / dailyTarget))
    : TERAFABX_COMMENT_INTERVAL_MS;
  const requiredIntervalMs = remaining > 0 && activeMinutesRemaining > 0
    ? Math.min(baseIntervalMs, Math.max(TERAFABX_COMMENT_MIN_INTERVAL_MS, Math.floor((activeMinutesRemaining * 60 * 1000) / remaining)))
    : baseIntervalMs;
  const postedPerActiveHour = activeMinutesElapsed > 0
    ? postedToday / (activeMinutesElapsed / 60)
    : 0;
  const requiredPerActiveHour = activeMinutesTotal > 0
    ? dailyTarget / (activeMinutesTotal / 60)
    : 0;
  const projectedTotal = activeMinutesElapsed > 0
    ? Math.round(postedPerActiveHour * (activeMinutesTotal / 60))
    : 0;
  const capacityPerDay = TERAFABX_COMMENT_MIN_INTERVAL_MS > 0
    ? Math.floor((activeMinutesTotal * 60 * 1000) / TERAFABX_COMMENT_MIN_INTERVAL_MS)
    : null;
  return {
    date: todayKey,
    dailyTarget,
    postedToday,
    remaining,
    targetByNow,
    behindBy: Math.max(0, targetByNow - postedToday),
    activeMinutesTotal: Math.round(activeMinutesTotal),
    activeMinutesElapsed: Math.round(activeMinutesElapsed),
    activeMinutesRemaining: Math.round(activeMinutesRemaining),
    baseIntervalMs,
    requiredIntervalMs,
    requiredPerActiveHour: Math.round(requiredPerActiveHour * 10) / 10,
    postedPerActiveHour: Math.round(postedPerActiveHour * 10) / 10,
    projectedTotal,
    capacityPerDay,
    onTrack: postedToday >= targetByNow,
    reached: remaining === 0,
  };
}

function nextTerafabxQuietPostingEnd(date = new Date()) {
  const formatter = new Intl.DateTimeFormat("en-CA", {
    timeZone: "Asia/Seoul",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
  const parts = Object.fromEntries(formatter.formatToParts(date).map((part) => [part.type, part.value]));
  const hour = kstHour(date);
  const end = TERAFABX_QUIET_POSTING_END_HOUR;
  const endKst = new Date(Date.UTC(Number(parts.year), Number(parts.month) - 1, Number(parts.day), end - 9, 0, 0));
  if (Number.isFinite(hour) && hour >= end) endKst.setUTCDate(endKst.getUTCDate() + 1);
  return endKst.toISOString();
}

function upsertTerafabxCommentReview(record) {
  const rows = loadTerafabxCommentReviewQueue();
  const key = String(record.targetUrl || "").split("?")[0];
  const index = rows.findIndex((item) => String(item.targetUrl || "").split("?")[0] === key);
  const next = index >= 0 ? { ...rows[index], ...record, updatedAt: new Date().toISOString() } : record;
  if (index >= 0) rows[index] = next;
  else rows.unshift(next);
  return { record: next, queue: saveTerafabxCommentReviewQueue(rows.slice(0, TERAFABX_VERIFIED_REVIEW_TARGET_COUNT * 2)) };
}

function terafabxPendingCommentPolicyFailure(item = {}) {
  const contextSafety = assessTerafabxGrokContextSafety({
    targetText: item.targetText,
    rootPostText: item.rootPostText,
  }, item.grokContext);
  if (!contextSafety.ok) {
    return { reason: contextSafety.reason || "unsafe_grok_context", errors: [] };
  }
  const policy = assessTerafabxCurrentCommentPolicy(item);
  if (!policy.ok) {
    return { reason: "current_comment_policy", errors: policy.errors || [] };
  }
  return null;
}

function pendingTerafabxCommentPosts(state = loadTerafabxState()) {
  const postedTargets = new Set((state.commentHistory || [])
    .map((item) => normalizeXStatusUrl(item.targetUrl || ""))
    .filter(Boolean));
  return Array.isArray(state.pendingCommentPosts)
    ? state.pendingCommentPosts.filter((item) => {
      if (!item || item.status === "posted") return false;
      const targetUrl = normalizeXStatusUrl(item.targetUrl || "");
      if (postedTargets.has(targetUrl)) return false;
      return !terafabxPendingCommentPolicyFailure(item);
    })
    : [];
}

function enqueueTerafabxPendingCommentPost(record, options = {}) {
  const previous = loadTerafabxState();
  const pending = pendingTerafabxCommentPosts(previous);
  const targetUrl = normalizeXStatusUrl(record.targetUrl || "");
  if (record.manual !== true && !["own_post_reply", "today_post_reply"].includes(String(record.source || options.source || ""))) {
    const cap = terafabxCommentAuthorCapDisposition(previous, { ...record, targetUrl }, new Date(), { excludePendingTargetUrl: targetUrl });
    if (!cap.allowed) {
      logEvent("terafabx_comment_pending_enqueue_skipped", {
        targetUrl,
        reason: cap.reason,
        handle: cap.usage.handle,
        used: cap.usage.used,
        limit: cap.usage.limit,
        source: options.source || record.source || "",
      });
      return { ...record, targetUrl, skipped: true, reason: cap.reason, retryAt: cap.retryAt };
    }
  }
  const policyFailure = terafabxPendingCommentPolicyFailure(record);
  if (policyFailure) {
    logEvent("terafabx_comment_pending_enqueue_skipped", {
      targetUrl,
      reason: policyFailure.reason,
      errors: policyFailure.errors,
      source: options.source || record.source || "",
    });
    return {
      ...record,
      targetUrl,
      skipped: true,
      reason: policyFailure.reason,
      errors: policyFailure.errors,
    };
  }
  const contextSafety = assessTerafabxGrokContextSafety({
    targetText: record.targetText,
    rootPostText: record.rootPostText,
  }, record.grokContext);
  if (!contextSafety.ok) {
    logEvent("terafabx_comment_pending_enqueue_skipped", {
      targetUrl,
      reason: contextSafety.reason,
      source: options.source || record.source || "",
    });
    return { ...record, targetUrl, skipped: true, reason: contextSafety.reason };
  }
  const alreadyPosted = (previous.commentHistory || []).some((item) => normalizeXStatusUrl(item.targetUrl || "") === targetUrl);
  if (alreadyPosted) {
    logEvent("terafabx_comment_pending_enqueue_skipped", { targetUrl, reason: "already_posted", source: options.source || record.source || "" });
    return { ...record, targetUrl, skipped: true, reason: "already_posted" };
  }
  const filtered = pending.filter((item) => normalizeXStatusUrl(item.targetUrl || "") !== targetUrl);
  const item = {
    ...record,
    targetUrl,
    status: "pending",
    queuedAt: record.queuedAt || new Date().toISOString(),
    capDate: record.capDate || formatKstDateKey(record.queuedAt || new Date()),
    attempts: Number(record.attempts || 0),
  };
  const seenTargets = Array.from(new Set([targetUrl, ...(previous.seenTargets || [])])).slice(0, 500);
  const update = {
    pendingCommentPosts: [item, ...filtered],
    seenTargets,
  };
  if (options.updateLastRun !== false) {
    Object.assign(update, {
      lastCommentRunAt: item.queuedAt,
      lastCommentStatus: "deferred",
      lastCommentError: null,
      lastComment: item.comment,
      lastCommentTarget: targetUrl,
    });
  }
  saveTerafabxState(update);
  logEvent(options.eventType || "terafabx_comment_deferred", {
    targetUrl,
    comment: item.comment,
    quietUntil: nextTerafabxQuietPostingEnd(),
    source: options.source || item.source || "",
    pendingCount: filtered.length + 1,
  });
  return item;
}

function removeTerafabxPendingCommentPost(targetUrl) {
  const previous = loadTerafabxState();
  const normalized = normalizeXStatusUrl(targetUrl || "");
  const pending = pendingTerafabxCommentPosts(previous);
  const nextPending = pending.filter((item) => normalizeXStatusUrl(item.targetUrl || "") !== normalized);
  saveTerafabxState({ pendingCommentPosts: nextPending });
  return { before: pending.length, after: nextPending.length };
}

function quarantineTerafabxPendingCommentPost(targetUrl, reason = "manual_quality_audit") {
  const previous = loadTerafabxState();
  const normalized = normalizeXStatusUrl(targetUrl || "");
  const pending = pendingTerafabxCommentPosts(previous);
  const target = pending.find((item) => normalizeXStatusUrl(item.targetUrl || "") === normalized);
  if (!target) return { ok: false, targetUrl: normalized, reason: "pending_target_not_found", pendingCount: pending.length };
  const failedAt = new Date().toISOString();
  const failed = {
    ...target,
    status: "error",
    errorAt: failedAt,
    failedReason: "manual_quality_audit",
    lastError: cleanSocialText(reason || "manual_quality_audit"),
  };
  const remaining = pending.filter((item) => normalizeXStatusUrl(item.targetUrl || "") !== normalized);
  saveTerafabxState({
    pendingCommentPosts: remaining,
    failedPendingCommentPosts: [failed, ...(previous.failedPendingCommentPosts || [])].slice(0, 300),
  });
  logEvent("terafabx_pending_comment_manual_quality_quarantined", {
    targetUrl: normalized,
    comment: target.comment,
    reason: failed.lastError,
    pendingCount: remaining.length,
  });
  return { ok: true, targetUrl: normalized, comment: target.comment, reason: failed.lastError, pendingCount: remaining.length };
}

function formatKstDateKey(value) {
  const date = value ? new Date(value) : new Date();
  if (!Number.isFinite(date.getTime())) return "";
  return new Intl.DateTimeFormat("sv-SE", {
    timeZone: "Asia/Seoul",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(date);
}

function nextKstDateBoundary(value = new Date()) {
  const key = formatKstDateKey(value);
  if (!key) return new Date(NaN);
  return new Date(new Date(`${key}T00:00:00+09:00`).getTime() + 24 * 60 * 60 * 1000);
}

function terafabxCommentAuthorHandle(record = {}) {
  return String(parseXStatusUrl(normalizeXStatusUrl(record.targetUrl || ""))?.handle || "").toLowerCase();
}

function terafabxCommentAuthorDailyUsage(state = {}, record = {}, nowValue = new Date(), options = {}) {
  const now = nowValue instanceof Date ? nowValue : new Date(nowValue || Date.now());
  const date = formatKstDateKey(now);
  const handle = terafabxCommentAuthorHandle(record);
  const limit = Math.max(1, Number(options.limit || TERAFABX_COMMENT_AUTHOR_DAILY_LIMIT));
  const ordinary = (item) => !["own_post_reply", "today_post_reply"].includes(String(item?.source || ""));
  const posted = (state.commentHistory || []).filter((item) => (
    ordinary(item)
    && terafabxCommentAuthorHandle(item) === handle
    && Boolean(item.replyUrl)
    && formatKstDateKey(item.postedAt || item.at) === date
  )).length;
  const excludedTarget = normalizeXStatusUrl(options.excludePendingTargetUrl || "");
  const reserved = options.includePending === false ? 0 : (state.pendingCommentPosts || []).filter((item) => (
    ordinary(item)
    && item?.status !== "posted"
    && normalizeXStatusUrl(item.targetUrl || "") !== excludedTarget
    && terafabxCommentAuthorHandle(item) === handle
    && formatKstDateKey(item.capDate || item.queuedAt || now) === date
  )).length;
  const used = posted + reserved;
  return {
    handle,
    date,
    posted,
    reserved,
    used,
    limit,
    allowed: Boolean(handle && date) && used < limit,
    retryAt: nextKstDateBoundary(now).toISOString(),
  };
}

function terafabxCommentAuthorCapDisposition(state = {}, record = {}, nowValue = new Date(), options = {}) {
  const usage = terafabxCommentAuthorDailyUsage(state, record, nowValue, options);
  return usage.allowed
    ? { allowed: true, reason: null, retryAt: null, usage }
    : { allowed: false, reason: usage.handle ? "author_daily_cap_reached" : "author_handle_missing", retryAt: usage.retryAt, usage };
}

function deferTerafabxPendingCommentForAuthorCap(item = {}, retryAt) {
  return {
    ...item,
    status: "pending",
    nextAttemptAt: retryAt,
    lastFailureReason: "author_daily_cap_reached",
    updatedAt: new Date().toISOString(),
  };
}

function terafabxOwnRootReplyUsage(state = {}, rootPostUrl = "", options = {}) {
  const normalized = normalizeXStatusUrl(rootPostUrl);
  const limit = Math.max(1, Number(options.limit || TERAFABX_OWN_ROOT_REPLY_LIMIT));
  const posted = (state.ownPostReplyHistory || []).filter((item) => (
    normalizeXStatusUrl(item.rootPostUrl || "") === normalized && Boolean(item.replyUrl)
  )).length;
  const reserved = (state.ownPostReplyManualQueue || []).filter((item) => (
    normalizeXStatusUrl(item.postUrl || "") === normalized
    && ["queued", "running"].includes(String(item.status || ""))
    && item.id !== options.excludeQueueRequestId
  )).reduce((count, item) => count + Math.max(1, Math.min(limit, Number(item.options?.limit || 1))), 0);
  const used = posted + reserved;
  return { rootPostUrl: normalized, posted, reserved, used, limit, allowed: Boolean(normalized) && used < limit };
}

function terafabxWeightedReplyDecision(state = {}, options = {}) {
  const threshold = Math.max(1, Number(options.threshold || TERAFABX_WEIGHTED_REPLY_THRESHOLD));
  const rawCount = typeof state === "number" ? state : state.successfulAutoCommentsSinceOwnReply;
  const count = Math.max(0, Number(rawCount || 0));
  return { due: count >= threshold, count, threshold };
}

function nextTerafabxWeightedReplyCount(current, kind, succeeded) {
  const count = Math.max(0, Number(current || 0));
  if (!succeeded) return count;
  return kind === "own_post_reply" ? 0 : count + 1;
}

function terafabxWeightedReplyRunDisposition(state = {}, options = {}) {
  const decision = terafabxWeightedReplyDecision(state);
  const now = options.now instanceof Date ? options.now : new Date(options.now || Date.now());
  const lastAttemptMs = Date.parse(state.lastWeightedOwnReplyAttemptAt || "") || 0;
  const retryMs = Math.max(0, Number(options.retryMs ?? TERAFABX_WEIGHTED_REPLY_RETRY_MS));
  const cooldownReady = now.getTime() - lastAttemptMs >= retryMs;
  const blockedBy = [];
  if (options.quiet) blockedBy.push("quiet_posting_time");
  if (options.ownReplyBusy) blockedBy.push("own_reply_busy");
  if (!cooldownReady) blockedBy.push("retry_cooldown");
  return { ...decision, allowed: decision.due && blockedBy.length === 0, blockedBy, cooldownReady };
}

function recentKstDateKeys(totalDays = 30) {
  const now = new Date();
  const keys = [];
  for (let i = totalDays - 1; i >= 0; i -= 1) {
    const date = new Date(now);
    date.setDate(now.getDate() - i);
    keys.push(formatKstDateKey(date));
  }
  return keys;
}

const COMMENT_QUALITY_STOPWORDS = new Set([
  "구독하기",
  "관련",
  "조회수",
  "오전",
  "오후",
  "2026년",
  "입니다",
  "있습니다",
  "같아요",
  "이네요",
  "하네요",
  "그렇군요",
  "저도",
  "정말",
  "너무",
  "오늘",
  "이번",
  "그냥",
]);

function commentQualityTokens(value) {
  return Array.from(new Set(String(value || "")
    .replace(/https?:\/\/\S+/gi, " ")
    .replace(/@\w+/g, " ")
    .match(/[가-힣A-Za-z]{2,}/g) || []))
    .map((token) => token.toLowerCase())
    .filter((token) => token.length >= 2 && !COMMENT_QUALITY_STOPWORDS.has(token));
}

function commentQualityGrade(score) {
  if (score >= 85) return "A";
  if (score >= 70) return "B";
  if (score >= 55) return "C";
  return "D";
}

function scoreTerafabxCommentQuality(comment, targetText, duplicateCount = 1) {
  const text = String(comment || "").trim();
  if (!text) {
    return { score: 0, grade: "D", reasons: ["empty_comment"] };
  }
  let score = 70;
  const reasons = [];
  const length = Array.from(text).length;
  if (length >= 10 && length <= 45) {
    score += 10;
    reasons.push("good_length");
  } else if (length >= 6 && length < 10) {
    score += 2;
    reasons.push("short_but_usable");
  } else if (length < 6) {
    score -= 25;
    reasons.push("too_short");
  } else {
    score -= 8;
    reasons.push("too_long");
  }

  const targetTokens = commentQualityTokens(targetText);
  const commentTokens = commentQualityTokens(text);
  const overlap = commentTokens.filter((token) => targetTokens.includes(token));
  if (overlap.length >= 2) {
    score += 12;
    reasons.push("specific_to_target");
  } else if (overlap.length === 1) {
    score += 6;
    reasons.push("some_target_context");
  } else {
    score -= 18;
    reasons.push("no_target_keyword_overlap");
  }

  if (/^(아\s*)?(그렇군요|좋네요|재밌네요|대박|맞아요|그러네요)[.!~\s]*$/i.test(text) || (/^(아\s*)?(그렇군요|좋네요|재밌네요|대박|맞아요|그러네요)/i.test(text) && overlap.length < 2)) {
    score -= 10;
    reasons.push("generic_reply");
  }
  if (/https?:\/\/|@\w+/.test(text)) {
    score -= 12;
    reasons.push("contains_link_or_handle");
  }
  if (duplicateCount > 1) {
    score -= Math.min(25, (duplicateCount - 1) * 12);
    reasons.push("duplicate_comment_text");
  }
  if (/[?？]$/.test(text) && overlap.length >= 1) {
    score += 3;
    reasons.push("engaging_question");
  }

  const finalScore = Math.max(0, Math.min(100, Math.round(score)));
  return {
    score: finalScore,
    grade: commentQualityGrade(finalScore),
    reasons,
  };
}

function publishedDiscoveryTime(row, nowMs = Date.now()) {
  if (!row) return "";
  if (row.status === "posted") return row.postedAt || row.scheduledPostAt || "";
  if (row.status === "scheduled") {
    const scheduledMs = new Date(row.scheduledPostAt || 0).getTime();
    if (Number.isFinite(scheduledMs) && scheduledMs <= nowMs) {
      return row.scheduledPostAt || row.postedAt || "";
    }
  }
  return "";
}

function isPublishedDiscoveryRow(row, nowMs = Date.now()) {
  return Boolean(publishedDiscoveryTime(row, nowMs));
}

function dashboardDiscoveryRow(row, nowMs = Date.now()) {
  if (row?.status === "scheduled" && isPublishedDiscoveryRow(row, nowMs)) {
    return {
      ...row,
      status: "posted",
      postedAt: row.scheduledPostAt || row.postedAt,
      scheduledPostAt: null,
    };
  }
  return row;
}

function mirrorHistoryPublishedTime(entry, nowMs = Date.now()) {
  if (!entry) return "";
  if (entry.status === "posted") return entry.completedAt || entry.postedAt || entry.scheduledAt || "";
  if (entry.status === "scheduled") {
    const scheduledMs = new Date(entry.scheduledAt || 0).getTime();
    if (Number.isFinite(scheduledMs) && scheduledMs <= nowMs) {
      return entry.scheduledAt || entry.completedAt || "";
    }
  }
  return "";
}

function mirrorHistoryDashboardRow(entry, nowMs = Date.now()) {
  const canonicalUrl = String(entry?.canonicalUrl || "").trim();
  if (!canonicalUrl) return null;
  const publishedAt = mirrorHistoryPublishedTime(entry, nowMs);
  const scheduledMs = new Date(entry.scheduledAt || 0).getTime();
  const isFutureScheduled = entry.status === "scheduled" && Number.isFinite(scheduledMs) && scheduledMs > nowMs;
  if (!publishedAt && !isFutureScheduled) return null;
  let author = "mirror-history";
  try {
    author = new URL(canonicalUrl).pathname.split("/")[1]?.replace("@", "") || author;
  } catch {}
  return {
    canonicalUrl,
    xPostUrl: normalizeXStatusUrl(entry.postUrl || "") || null,
    author,
    textPreview: "이전 미러링 이력",
    mediaPreviewUrl: "",
    likeCount: 0,
    mediaCount: Number(entry.mediaCount || 0),
    viralScore: 0,
    criteria: JSON.stringify({ mirrorHistory: true }),
    status: publishedAt ? "posted" : "scheduled",
    scheduledPostAt: publishedAt ? null : entry.scheduledAt,
    discoveredAt: entry.completedAt || entry.scheduledAt || "",
    postedAt: publishedAt || null,
    lastError: null,
    attempts: 0,
  };
}

function mergeDiscoveryRowsWithMirrorHistory(rows, nowMs = Date.now(), historyEntries = loadMirrorHistory()) {
  const byUrl = new Map((rows || []).map((row) => [row.canonicalUrl, row]));
  for (const entry of historyEntries || []) {
    const historyRow = mirrorHistoryDashboardRow(entry, nowMs);
    if (!historyRow) continue;
    const existing = byUrl.get(historyRow.canonicalUrl);
    if (!existing) {
      byUrl.set(historyRow.canonicalUrl, historyRow);
      continue;
    }
    const next = { ...existing };
    next.xPostUrl = historyRow.xPostUrl || existing.xPostUrl || null;
    next.mediaCount = Math.max(Number(existing.mediaCount || 0), Number(historyRow.mediaCount || 0));
    if (historyRow.status === "posted") {
      next.status = "posted";
      next.postedAt = historyRow.postedAt;
      next.scheduledPostAt = null;
      next.lastError = null;
    } else if (!isPublishedDiscoveryRow(existing, nowMs)) {
      next.status = "scheduled";
      next.scheduledPostAt = historyRow.scheduledPostAt;
    }
    byUrl.set(historyRow.canonicalUrl, next);
  }
  return Array.from(byUrl.values());
}

function normalizeTerafabxPostTextForMatch(value = "") {
  return cleanSocialText(value).replace(/\s+/g, " ").trim().toLowerCase();
}

function terafabxCompletedReplyTargetsByRoot(state = {}) {
  const byRoot = new Map();
  for (const item of [...(state.commentHistory || []), ...(state.ownPostReplyHistory || [])]) {
    if (!item?.replyUrl) continue;
    const rootUrl = normalizeXStatusUrl(item.rootPostUrl || "");
    const targetUrl = normalizeXStatusUrl(item.targetUrl || item.targetCommentUrl || "");
    if (!parseXStatusUrl(rootUrl)?.id || !parseXStatusUrl(targetUrl)?.id) continue;
    if (!byRoot.has(rootUrl)) byRoot.set(rootUrl, new Map());
    byRoot.get(rootUrl).set(targetUrl, item);
  }
  return byRoot;
}

function buildTerafabxOwnPostReplyCompletionMetrics(state = loadTerafabxState()) {
  const completedByRoot = terafabxCompletedReplyTargetsByRoot(state);
  const backlogByRoot = new Map(normalizeTerafabxOwnPostCoverageBacklog(state.ownPostCoverageBacklog)
    .map((item) => [item.url, item]));
  const snapshots = state.ownPostReplyCoverage && typeof state.ownPostReplyCoverage === "object"
    ? state.ownPostReplyCoverage
    : {};
  const roots = new Set([...completedByRoot.keys(), ...backlogByRoot.keys(), ...Object.keys(snapshots)]);
  const metrics = new Map();

  for (const rootUrl of roots) {
    const completedRows = completedByRoot.get(rootUrl) || new Map();
    const latestHistory = Array.from(completedRows.values())
      .sort((a, b) => String(b.postedAt || b.at || "").localeCompare(String(a.postedAt || a.at || "")))[0] || null;
    const snapshot = snapshots[rootUrl] || {};
    const backlog = backlogByRoot.get(rootUrl) || {};
    const direct = snapshot.fullScan === true;
    const completedCount = Math.max(completedRows.size, direct ? Number(snapshot.completedCount || 0) : 0);
    const remainingCount = direct ? Math.max(0, Number(snapshot.remainingEligibleCount || 0)) : null;
    const rawReplyCount = Math.max(0, Number(snapshot.rawReplyCount || backlog.replies || 0));
    const totalCount = direct
      ? Math.max(completedCount + remainingCount, Number(snapshot.totalEligibleCount || 0))
      : rawReplyCount > 0
        ? Math.max(completedCount, rawReplyCount)
        : null;
    const percentage = totalCount === 0
      ? 100
      : totalCount
        ? Math.min(100, Math.round((completedCount / totalCount) * 1000) / 10)
        : null;
    metrics.set(rootUrl, {
      rootPostUrl: rootUrl,
      rootPostText: String(snapshot.rootPostText || latestHistory?.rootPostText || ""),
      completedCount,
      totalCount,
      remainingCount: totalCount === null ? null : Math.max(0, totalCount - completedCount),
      percentage,
      exact: direct,
      scheduled: snapshot.countRefreshScheduled === true,
      source: snapshot.countRefreshScheduled === true
        ? "scheduled-full-conversation"
        : direct
          ? "x-direct-full-scroll"
          : totalCount
            ? "x-reply-count-estimate"
            : "history-only",
      checkedAt: snapshot.countRefreshCheckedAt || snapshot.checkedAt || backlog.lastCheckedAt || null,
      rawReplyCount: rawReplyCount || null,
      collectedDirectReplyCount: direct ? Math.max(0, Number(snapshot.directReplyCount || 0)) : null,
    });
  }
  return metrics;
}

function enrichDiscoveryRowsWithReplyCompletion(rows = [], state = loadTerafabxState()) {
  const metrics = buildTerafabxOwnPostReplyCompletionMetrics(state);
  const unusedRoots = new Set(metrics.keys());
  const result = (rows || []).map((row) => ({ ...row }));
  const assign = (row, rootUrl) => {
    const metric = metrics.get(rootUrl);
    if (!metric) return false;
    row.xPostUrl = rootUrl;
    row.replyCompletion = metric;
    unusedRoots.delete(rootUrl);
    return true;
  };

  for (const row of result) {
    const xPostUrl = normalizeXStatusUrl(row.xPostUrl || "");
    if (xPostUrl) assign(row, xPostUrl);
  }
  for (const row of result) {
    if (row.replyCompletion || !isPublishedDiscoveryRow(row)) continue;
    const text = normalizeTerafabxPostTextForMatch(row.textPreview || "");
    if (!text) continue;
    const exact = Array.from(unusedRoots).find((rootUrl) => (
      normalizeTerafabxPostTextForMatch(metrics.get(rootUrl)?.rootPostText || "") === text
    ));
    if (exact) assign(row, exact);
  }
  for (const row of result) {
    if (row.replyCompletion || !isPublishedDiscoveryRow(row)) continue;
    const postedAtMs = Date.parse(publishedDiscoveryTime(row));
    if (!Number.isFinite(postedAtMs)) continue;
    const nearest = Array.from(unusedRoots)
      .map((rootUrl) => ({ rootUrl, delta: Math.abs(xStatusCreatedAtMs(rootUrl) - postedAtMs) }))
      .filter((item) => Number.isFinite(item.delta) && item.delta <= 2 * 60 * 1000)
      .sort((a, b) => a.delta - b.delta)[0];
    if (nearest) assign(row, nearest.rootUrl);
  }
  return result;
}

function compactAutomationGrokContext(context) {
  if (!context || typeof context !== "object") return null;
  const summary = String(context.summary || context.contextSummary || "").trim();
  const keyPoints = Array.isArray(context.keyPoints)
    ? context.keyPoints.map((item) => String(item || "").trim()).filter(Boolean).slice(0, 8)
    : [];
  if (!summary && !keyPoints.length) return null;
  return {
    summary,
    keyPoints,
    provider: String(context.provider || "").trim(),
  };
}

function compactAutomationGeminiReview(review) {
  if (!review || typeof review !== "object") return null;
  const finalJudge = review.finalJudge && typeof review.finalJudge === "object"
    ? {
      score: Number.isFinite(Number(review.finalJudge.score)) ? Number(review.finalJudge.score) : null,
      reason: String(review.finalJudge.reason || "").trim(),
    }
    : null;
  return {
    score: Number.isFinite(Number(review.score)) ? Number(review.score) : null,
    decision: String(review.decision || "").trim(),
    reason: String(review.reason || "").trim(),
    finalJudge,
  };
}

function buildAutomationDashboardData(allRows = [], nowMs = Date.now(), options = {}) {
  const state = loadTerafabxState();
  const requestedDate = String(options.timelineDate || "").trim();
  const timelineDate = requestedDate === "all" || /^\d{4}-\d{2}-\d{2}$/.test(requestedDate)
    ? requestedDate
    : "all";
  const defaultLimit = 200;
  const requestedLimit = Number(options.timelineLimit || defaultLimit);
  const timelineLimit = Number.isFinite(requestedLimit)
    ? Math.min(500, Math.max(25, Math.floor(requestedLimit)))
    : defaultLimit;
  const matchesTimelineDate = (item) => timelineDate === "all" || item.date === timelineDate;

  const reviewStats = loadTerafabxCommentReviewQueue()
    .filter((item) => item && item.at)
    .map((item) => ({
      item,
      at: item.at,
      date: formatKstDateKey(item.at),
      status: item.status || "review",
      posted: Boolean(item.posted),
    }))
    .filter((item) => item.date)
    .sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());
  const commentTextCounts = (state.commentHistory || []).reduce((acc, item) => {
    const key = String(item?.comment || "").trim();
    if (key) acc.set(key, (acc.get(key) || 0) + 1);
    return acc;
  }, new Map());
  const commentStats = (state.commentHistory || [])
    .filter((item) => item && item.at)
    .map((item) => {
      const localQuality = scoreTerafabxCommentQuality(
        item.comment || "",
        item.targetText || "",
        commentTextCounts.get(String(item.comment || "").trim()) || 1,
      );
      const finalJudgeScore = Number(item.geminiReview?.finalJudge?.score ?? item.geminiReview?.score);
      const hasFinalJudgeScore = Number.isFinite(finalJudgeScore);
      const qualityScore = hasFinalJudgeScore ? finalJudgeScore : localQuality.score;
      return {
        item,
        at: item.at,
        date: formatKstDateKey(item.at),
        qualityScore,
        qualitySource: hasFinalJudgeScore ? "independent_headless_judge" : "local",
        qualityGrade: commentQualityGrade(qualityScore),
        qualityReasons: hasFinalJudgeScore ? [item.geminiReview?.finalJudge?.reason || item.geminiReview?.reason || "independent_headless_judge_score"].filter(Boolean) : localQuality.reasons,
        localQualityScore: localQuality.score,
        localQualityGrade: localQuality.grade,
      };
    })
    .filter((item) => item.date)
    .sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());
  const heartStats = (state.heartHistory || [])
    .filter((item) => item && item.at)
    .map((item) => ({
      at: item.at,
      date: formatKstDateKey(item.at),
      count: Number(item.count || 0),
      manual: Boolean(item.manual),
    }))
    .filter((item) => item.date)
    .sort((a, b) => new Date(b.at).getTime() - new Date(a.at).getTime());

  const compactReview = ({ item, at, date, status, posted }) => ({
    id: item.id || `${at}-${item.targetUrl || item.targetId || ""}`,
    at,
    date,
    status,
    source: item.source || "",
    follower: item.follower || null,
    targetUrl: item.targetUrl || "",
    targetId: item.targetId || "",
    targetText: item.targetText || "",
    grokComment: item.grokComment || "",
    grokContext: compactAutomationGrokContext(item.grokContext),
    comment: item.comment || "",
    geminiReview: compactAutomationGeminiReview(item.geminiReview),
    generator: item.generator || "",
    posted,
    manual: Boolean(item.manual),
  });
  const selectedReviewStats = reviewStats.filter(matchesTimelineDate);
  const selectedCommentStats = commentStats.filter(matchesTimelineDate);
  const selectedHeartStats = heartStats.filter(matchesTimelineDate);
  const reviewQueue = selectedReviewStats.slice(0, timelineLimit).map(compactReview);
  const pendingReviewQueue = reviewQueue.filter((item) => !item.posted && item.status !== "error");
  const postedReviewQueue = reviewQueue.filter((item) => item.posted);
  const errorReviewQueue = reviewQueue.filter((item) => !item.posted && item.status === "error");
  const commentTimeline = selectedCommentStats.slice(0, timelineLimit).map((stat) => {
    const item = stat.item;
    const handle = getXStatusUrlHandle(item.targetUrl || "");
    return {
      at: stat.at,
      date: stat.date,
      source: item.source || "",
      targetUrl: item.targetUrl || "",
      targetId: item.targetId || "",
      targetText: item.targetText || "",
      comment: item.comment || "",
      grokComment: item.grokComment || "",
      grokContext: compactAutomationGrokContext(item.grokContext),
      replyUrl: item.replyUrl || "",
      generator: item.generator || "",
      manual: Boolean(item.manual),
      follower: {
        handle,
        profileUrl: handle ? `https://x.com/${handle}` : "",
        avatarUrl: item.follower?.avatarUrl || "",
        avatarSource: item.follower?.avatarSource || "",
      },
      geminiReview: compactAutomationGeminiReview(item.geminiReview),
      qualityScore: stat.qualityScore,
      qualitySource: stat.qualitySource,
      qualityGrade: stat.qualityGrade,
      qualityReasons: stat.qualityReasons,
      localQualityScore: stat.localQualityScore,
      localQualityGrade: stat.localQualityGrade,
    };
  });
  const heartTimeline = selectedHeartStats.slice(0, timelineLimit).map((item) => ({ ...item }));
  const flowDays = new Map(recentKstDateKeys(30).map((date) => [
    date,
    { date, posted: 0, comments: 0, hearts: 0 },
  ]));

  for (const row of allRows) {
    const publishedAt = publishedDiscoveryTime(row, nowMs);
    if (!publishedAt) continue;
    const date = formatKstDateKey(publishedAt);
    if (flowDays.has(date)) flowDays.get(date).posted += 1;
  }
  for (const item of commentStats) {
    if (flowDays.has(item.date)) flowDays.get(item.date).comments += 1;
  }
  for (const item of heartStats) {
    if (flowDays.has(item.date)) flowDays.get(item.date).hearts += item.count;
  }

  const availableDates = Array.from(new Set([
    ...commentStats.map((item) => item.date),
    ...reviewStats.map((item) => item.date),
    ...heartStats.map((item) => item.date),
  ])).sort((a, b) => b.localeCompare(a));
  const postedCount = allRows.filter((row) => isPublishedDiscoveryRow(row, nowMs)).length;
  const heartCount = heartStats.reduce((total, item) => total + item.count, 0);
  const commentQualityScore = commentStats.length
    ? Math.round(commentStats.reduce((total, item) => total + Number(item.qualityScore || 0), 0) / commentStats.length)
    : 0;
  const scopeQualityScore = selectedCommentStats.length
    ? Math.round(selectedCommentStats.reduce((total, item) => total + Number(item.qualityScore || 0), 0) / selectedCommentStats.length)
    : null;
  const selectedPendingReviewCount = selectedReviewStats.filter((item) => !item.posted && item.status !== "error").length;
  const selectedPostedReviewCount = selectedReviewStats.filter((item) => item.posted).length;
  const selectedErrorReviewCount = selectedReviewStats.filter((item) => !item.posted && item.status === "error").length;
  return {
    summary: {
      postedCount,
      commentCount: commentStats.length,
      heartCount,
      commentQualityScore,
      commentQualityGrade: commentQualityGrade(commentQualityScore),
      lowQualityCommentCount: commentStats.filter((item) => Number(item.qualityScore || 0) < 70).length,
      commentReviewCount: reviewStats.length,
      pendingCommentReviewCount: reviewStats.filter((item) => !item.posted && item.status !== "error").length,
      postedCommentReviewCount: reviewStats.filter((item) => item.posted).length,
      errorCommentReviewCount: reviewStats.filter((item) => !item.posted && item.status === "error").length,
      lastCommentAt: commentStats[0]?.at || null,
      lastHeartAt: heartStats[0]?.at || null,
    },
    scopeMetrics: {
      date: timelineDate,
      commentCount: selectedCommentStats.length,
      reviewCount: selectedReviewStats.length,
      pendingReviewCount: selectedPendingReviewCount,
      postedReviewCount: selectedPostedReviewCount,
      errorReviewCount: selectedErrorReviewCount,
      qualityCount: selectedCommentStats.length,
      qualityAverage: scopeQualityScore,
      heartCount: selectedHeartStats.reduce((total, item) => total + item.count, 0),
      heartRunCount: selectedHeartStats.length,
      displayCount: selectedCommentStats.length + selectedPendingReviewCount,
    },
    timelinePage: {
      date: timelineDate,
      limit: timelineLimit,
      commentTotal: selectedCommentStats.length,
      commentReturned: commentTimeline.length,
      reviewTotal: selectedReviewStats.length,
      reviewReturned: reviewQueue.length,
      heartTotal: selectedHeartStats.length,
      heartReturned: heartTimeline.length,
      truncated: selectedCommentStats.length > commentTimeline.length
        || selectedReviewStats.length > reviewQueue.length
        || selectedHeartStats.length > heartTimeline.length,
    },
    flowDays: Array.from(flowDays.values()),
    commentTimeline,
    commentReviewQueue: pendingReviewQueue,
    postedCommentReviewQueue: postedReviewQueue,
    errorCommentReviewQueue: errorReviewQueue,
    heartTimeline,
    availableDates,
  };
}

function getTerafabxLockState() {
  try {
    const raw = fs.readFileSync(TERAFABX_LOCK_PATH, "utf8");
    const lock = JSON.parse(raw);
    const ageMs = Date.now() - new Date(lock.at || 0).getTime();
    if (lock.pid && lock.pid !== process.pid) {
      try {
        process.kill(lock.pid, 0);
      } catch {
        try { fs.unlinkSync(TERAFABX_LOCK_PATH); } catch {}
        logEvent("terafabx_stale_lock_removed", { path: TERAFABX_LOCK_PATH, ...lock, ageMs });
        return { busy: false, path: TERAFABX_LOCK_PATH, staleRemoved: true };
      }
    }
    return { busy: true, path: TERAFABX_LOCK_PATH, ageMs, ...lock };
  } catch {
    return { busy: false, path: TERAFABX_LOCK_PATH };
  }
}

function getTerafabxCommentXLockState() {
  try {
    const raw = fs.readFileSync(TERAFABX_COMMENT_X_LOCK_PATH, "utf8");
    const lock = JSON.parse(raw);
    const ageMs = Date.now() - new Date(lock.at || 0).getTime();
    if (lock.pid && lock.pid !== process.pid) {
      try {
        process.kill(lock.pid, 0);
      } catch {
        try { fs.unlinkSync(TERAFABX_COMMENT_X_LOCK_PATH); } catch {}
        logEvent("terafabx_comment_x_stale_lock_removed", { path: TERAFABX_COMMENT_X_LOCK_PATH, ...lock, ageMs });
        return { busy: false, path: TERAFABX_COMMENT_X_LOCK_PATH, staleRemoved: true };
      }
    }
    return { busy: true, path: TERAFABX_COMMENT_X_LOCK_PATH, ageMs, ...lock };
  } catch {
    return { busy: false, path: TERAFABX_COMMENT_X_LOCK_PATH };
  }
}

async function withTerafabxCommentXLock(action, fn, options = {}) {
  const wait = options.wait !== false;
  const timeoutMs = Number(options.timeoutMs || 6 * 60 * 1000);
  const staleMs = Number(options.staleMs || 10 * 60 * 1000);
  const pollMs = Number(options.pollMs || 1000);
  const startedAt = Date.now();
  let loggedWait = false;
  while (true) {
    const existing = getTerafabxCommentXLockState();
    if (!existing.busy || Number(existing.ageMs || 0) >= staleMs) {
      if (existing.busy && Number(existing.ageMs || 0) >= staleMs) {
        try { fs.unlinkSync(TERAFABX_COMMENT_X_LOCK_PATH); } catch {}
        logEvent("terafabx_comment_x_expired_lock_removed", { action, existingAction: existing.action || "unknown", ageMs: existing.ageMs });
      }
      break;
    }
    if (!wait) {
      throw new Error(`9236 headless X writer 사용 중: ${existing.action || "unknown"}`);
    }
    if (!loggedWait) {
      loggedWait = true;
      logEvent("terafabx_comment_x_lock_wait_start", { action, existingAction: existing.action || "unknown" });
    }
    if (Date.now() - startedAt > timeoutMs) {
      throw new Error(`9236 headless X writer 대기 시간 초과: ${existing.action || "unknown"}`);
    }
    await sleep(pollMs);
  }
  fs.writeFileSync(TERAFABX_COMMENT_X_LOCK_PATH, JSON.stringify({
    at: new Date().toISOString(),
    pid: process.pid,
    action,
    port: TERAFABX_COMMENT_X_CHROME_PORT,
  }, null, 2));
  try {
    return await fn();
  } finally {
    if (loggedWait) logEvent("terafabx_comment_x_lock_wait_end", { action, waitedMs: Date.now() - startedAt });
    try { fs.unlinkSync(TERAFABX_COMMENT_X_LOCK_PATH); } catch {}
  }
}

function getTerafabxAutoCommentResourceLockState(kind) {
  const resource = terafabxAutoCommentBrowserResources()[kind];
  if (!resource) return { busy: false, kind, path: "" };
  try {
    const lock = JSON.parse(fs.readFileSync(resource.lockPath, "utf8"));
    const ageMs = Date.now() - new Date(lock.at || 0).getTime();
    if (lock.pid && lock.pid !== process.pid) {
      try {
        process.kill(lock.pid, 0);
      } catch {
        try { fs.unlinkSync(resource.lockPath); } catch {}
        return { busy: false, kind, path: resource.lockPath, staleRemoved: true };
      }
    }
    return { busy: true, kind, path: resource.lockPath, ageMs, ...lock };
  } catch {
    return { busy: false, kind, path: resource.lockPath };
  }
}

async function withTerafabxAutoCommentResourceLock(kind, action, fn, options = {}) {
  const resource = terafabxAutoCommentBrowserResources()[kind];
  if (!resource) throw new Error(`알 수 없는 자동댓글 브라우저 리소스: ${kind}`);
  const timeoutMs = Number(options.timeoutMs || 6 * 60 * 1000);
  const startedAt = Date.now();
  let loggedWait = false;
  while (true) {
    const existing = getTerafabxAutoCommentResourceLockState(kind);
    if (!existing.busy || Number(existing.ageMs || 0) >= 10 * 60 * 1000) {
      if (existing.busy) try { fs.unlinkSync(resource.lockPath); } catch {}
      break;
    }
    if (options.wait === false) throw new Error(`${resource.port} 자동댓글 ${kind} 사용 중: ${existing.action || "unknown"}`);
    if (!loggedWait) {
      loggedWait = true;
      logEvent("terafabx_auto_comment_lock_wait_start", { kind, action, existingAction: existing.action || "unknown" });
    }
    if (Date.now() - startedAt > timeoutMs) throw new Error(`${resource.port} 자동댓글 ${kind} 대기 시간 초과`);
    await sleep(Number(options.pollMs || 250));
  }
  fs.writeFileSync(resource.lockPath, JSON.stringify({ at: new Date().toISOString(), pid: process.pid, action, port: resource.port }, null, 2));
  try {
    return await fn();
  } finally {
    if (loggedWait) logEvent("terafabx_auto_comment_lock_wait_end", { kind, action, waitedMs: Date.now() - startedAt });
    try { fs.unlinkSync(resource.lockPath); } catch {}
  }
}

async function withTerafabxLock(action, fn, options = {}) {
  const wait = Boolean(options.wait);
  const timeoutMs = Number(options.timeoutMs || 10 * 60 * 1000);
  const pollMs = Number(options.pollMs || 1000);
  const startedAt = Date.now();
  let loggedWait = false;
  while (true) {
    const existing = getTerafabxLockState();
    if (!existing.busy || Number(existing.ageMs || 0) >= 10 * 60 * 1000) break;
    if (!wait) {
      throw new Error(`9224 CDP lock 사용 중: ${existing.action || "unknown"}`);
    }
    if (!loggedWait) {
      loggedWait = true;
      logEvent("cdp_lock_wait_start", { action, existingAction: existing.action || "unknown" });
    }
    if (Date.now() - startedAt > timeoutMs) {
      throw new Error(`9224 CDP lock 대기 시간 초과: ${existing.action || "unknown"}`);
    }
    await sleep(pollMs);
  }
  fs.writeFileSync(TERAFABX_LOCK_PATH, JSON.stringify({ at: new Date().toISOString(), pid: process.pid, action }, null, 2));
  try {
    return await fn();
  } finally {
    if (loggedWait) logEvent("cdp_lock_wait_end", { action, waitedMs: Date.now() - startedAt });
    try { fs.unlinkSync(TERAFABX_LOCK_PATH); } catch {}
  }
}

async function withMirrorChromeLock(action, fn) {
  return withTerafabxLock(action, fn, { wait: true, timeoutMs: 20 * 60 * 1000 });
}

function cleanSocialText(value) {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function stripTerafabxListPrefix(value) {
  return String(value || "")
    .replace(/^\s*(?:(?:[-*•])\s+|(?:\d{1,3})[.)]\s+)/, "")
    .trim();
}

function validateTerafabxReply(value) {
  const text = cleanSocialText(value).replace(/^['"“”‘’]+|['"“”‘’]+$/g, "");
  if (!text) throw new Error("자동댓글이 비어 있습니다.");
  if (/[\r\n]/.test(text)) throw new Error("댓글은 한 줄이어야 합니다.");
  if (/(감정 회계|가성비 최고|독특하네요|훈훈하다|선남선녀|와 진짜|대박|ㄷㄷ|저격수|때려야|죽이네요|보고서|분석)/i.test(text)) {
    throw new Error(`금지/저품질 표현 감지: ${text}`);
  }
  if (/(죽|살인|칼|총|포탄|전쟁|성폭|강간|자살|마약|카지노|도박|투자|주식|주가|매수|매도|매매|포지션|손실|수익|차트|거래소|거래|암호화폐|코인|비트코인|에어드랍|에어드롭|토큰|스테이킹|온체인|블록체인|crypto|airdrop|token|exchange|wallet|blockchain|finance|financial|profit|loss|leverage|futures)/i.test(text)) {
    throw new Error(`민감 표현 감지: ${text}`);
  }
  return text;
}

function normalizeTerafabxGrokKeyPoints(value) {
  const source = Array.isArray(value)
    ? value
    : String(value || "").split(/\n|[•·]|(?:^|\s)[-\d]+[.)]?\s+/);
  return source
    .map((item) => cleanSocialText(stripTerafabxListPrefix(item)))
    .filter(Boolean)
    .slice(0, 5)
    .map((item) => item.slice(0, 240));
}

function normalizeTerafabxGrokResult(value) {
  const source = value && typeof value === "object" ? value : { reply: value };
  const replyRaw = source.reply
    || source.comment
    || source.finalReply
    || source.final_reply
    || source.grokComment
    || "";
  return {
    reply: validateTerafabxReply(stripTerafabxListPrefix(replyRaw)),
    contextSummary: cleanSocialText(source.contextSummary || source.context_summary || source.summary || source.analysis || source.context || "").slice(0, 1200),
    keyPoints: normalizeTerafabxGrokKeyPoints(source.keyPoints || source.key_points || source.points || []),
    rawPreview: String(source.rawPreview || source.raw || "").slice(0, 1200),
  };
}

function normalizeTerafabxContextResult(value) {
  const source = value && typeof value === "object" ? value : {};
  const replyRaw = source.reply || source.comment || source.finalReply || source.final_reply || "";
  return {
    reply: replyRaw ? validateTerafabxReply(stripTerafabxListPrefix(replyRaw)) : "",
    contextSummary: cleanSocialText(source.contextSummary || source.context_summary || source.summary || source.analysis || source.context || "").slice(0, 1200),
    keyPoints: normalizeTerafabxGrokKeyPoints(source.keyPoints || source.key_points || source.points || []),
    rawPreview: String(source.rawPreview || source.raw || "").slice(0, 1200),
    provider: String(source.provider || ""),
  };
}

function parseTerafabxGrokContext(raw) {
  const source = String(raw || "").trim();
  const parsed = JSON.parse(extractJsonObjectText(source));
  return normalizeTerafabxContextResult({
    reply: parsed.reply || parsed.comment || parsed.final_reply || parsed.finalReply,
    contextSummary: parsed.context_summary || parsed.contextSummary || parsed.analysis || parsed.context,
    keyPoints: parsed.key_points || parsed.keyPoints || parsed.points,
    rawPreview: source,
  });
}

function parseTerafabxGrokContextBatch(raw, targets = []) {
  const expected = Array.isArray(targets) ? targets : [];
  const rows = parseTerafabxJsonCollection(raw, ["items", "contexts", "results"]);
  const byIndex = new Map();
  for (const row of rows) {
    const index = Number(row?.index);
    if (!Number.isInteger(index) || index < 0 || index >= expected.length || byIndex.has(index)) continue;
    byIndex.set(index, normalizeTerafabxContextResult({
      reply: row.reply || row.comment || row.final_reply || row.finalReply,
      contextSummary: row.context_summary || row.contextSummary || row.analysis || row.context,
      keyPoints: row.key_points || row.keyPoints || row.points,
      rawPreview: String(raw || "").slice(0, 1200),
    }));
  }
  return expected.map((target, index) => {
    const context = byIndex.get(index);
    if (!context || !hasDetailedTerafabxGrokContext(context) || !context.reply) {
      return { ok: false, target, index, error: "Grok 묶음 문맥 분석 또는 댓글 초안 JSON이 비어 있거나 부족합니다." };
    }
    return { ok: true, target, index, context };
  });
}

function isTerafabxGrokNonJsonLimitText(raw) {
  const text = String(raw || "").trim();
  return /you['’]?ve\s+reached|limit\s+of\s+\d+\s+grok|questions?\s+per\s+\d+\s+hours?|주간\s*한도에\s*도달했습니다|\d{1,2}월\s*\d{1,2}일에\s*초기화됩니다|quota_limit/i.test(text);
}

function parseTerafabxGrokQuotaResetAt(raw, now = new Date()) {
  const match = String(raw || "").match(/(\d{1,2})월\s*(\d{1,2})일에\s*초기화/);
  if (!match) return new Date(now.getTime() + 6 * 60 * 60 * 1000).toISOString();
  const kstYear = Number(new Intl.DateTimeFormat("en-US", { timeZone: "Asia/Seoul", year: "numeric" }).format(now));
  const month = String(Number(match[1])).padStart(2, "0");
  const day = String(Number(match[2])).padStart(2, "0");
  let resetAt = new Date(`${kstYear}-${month}-${day}T00:00:00+09:00`);
  if (resetAt.getTime() <= now.getTime()) resetAt = new Date(`${kstYear + 1}-${month}-${day}T00:00:00+09:00`);
  return resetAt.toISOString();
}

function terafabxGrokIndividualBackoffUntil(nowMs = Date.now(), durationMs = 10 * 60 * 1000) {
  return new Date(Number(nowMs) + Math.max(60_000, Number(durationMs || 0))).toISOString();
}

function activeTerafabxGrokQuotaBlocker(state = loadTerafabxState(), now = Date.now()) {
  const until = Date.parse(state.grokQuotaBackoffUntil || "");
  if (!Number.isFinite(until) || until <= now) return null;
  return {
    until: new Date(until).toISOString(),
    message: state.grokQuotaMessage || `Grok 주간 사용량 제한으로 ${new Date(until).toISOString()}까지 문맥 생성을 중단합니다.`,
  };
}

function terafabxGrokContextForRecord(value) {
  const grok = normalizeTerafabxContextResult(value);
  return {
    summary: grok.contextSummary,
    keyPoints: grok.keyPoints,
    rawPreview: grok.rawPreview,
    provider: String(value?.provider || ""),
  };
}

function hasDetailedTerafabxGrokContext(value) {
  const grok = normalizeTerafabxContextResult(value);
  return grok.contextSummary.length >= 30 && grok.keyPoints.length >= 1;
}

function isConfirmedTerafabxGrokContext(value) {
  const provider = String(value?.provider || "");
  return hasDetailedTerafabxGrokContext(value)
    && /^(?:(?:web|cli)-context(?:-batch)?|direct-codex-context)$/.test(provider)
    && !isTerafabxGrokContextFallback(value)
    && value?.rawPreview !== "local-root-context-fallback";
}

function assertConfirmedTerafabxGrokContext(value) {
  if (!isConfirmedTerafabxGrokContext(value)) {
    const error = new Error("검증된 상세 문맥 분석 성공 기록이 없어 댓글·대댓글을 게시하지 않습니다.");
    error.code = "TERAFABX_GROK_CONTEXT_REQUIRED";
    throw error;
  }
  return value;
}

function isTerafabxGrokContextFallback(value) {
  const grok = normalizeTerafabxContextResult(value);
  return grok.rawPreview === "local_text_context_after_grok_failure"
    || grok.contextSummary.startsWith("Grok 문맥 분석 실패 후 원문 텍스트를 직접 사용한다.");
}

function parseTerafabxGrokResult(raw) {
  const source = String(raw || "").trim();
  let parsed = null;
  try {
    parsed = JSON.parse(extractJsonObjectText(source));
  } catch {}
  if (parsed && typeof parsed === "object") {
    return normalizeTerafabxGrokResult({
      reply: parsed.reply || parsed.comment || parsed.final_reply || parsed.finalReply,
      contextSummary: parsed.context_summary || parsed.contextSummary || parsed.analysis || parsed.context,
      keyPoints: parsed.key_points || parsed.keyPoints || parsed.points,
      rawPreview: source,
    });
  }
  const firstLine = source
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean)
    .find((line) => !/^```/.test(line)) || source;
  return normalizeTerafabxGrokResult({ reply: firstLine, rawPreview: source });
}

function terafabxPromptContextLines(target = {}) {
  const targetText = cleanSocialText(target.targetText || target.text || "");
  const rootPostText = cleanSocialText(target.rootPostText || "");
  const rootPostUrl = normalizeXStatusUrl(target.rootPostUrl || "");
  if (rootPostUrl || rootPostText) {
    if (!rootPostText) throw new Error("부모 원글 문맥이 비어 있어 대댓글을 생성하지 않습니다.");
    return [
      "대댓글 문맥 규칙: 부모 원글과 답글 대상 댓글을 하나의 대화로 함께 해석해라.",
      "대상 댓글이 주어·장면을 생략하면 부모 원글에서 상속하고, 이미 보이는 대상을 누구·무엇·어떤 대상인지 모르는 듯 되묻지 마라. 단, 대상 댓글 작성자가 직접 물은 내용을 함께 궁금해하는 맞장구는 가능하다.",
      `부모 원글 URL: ${rootPostUrl}`,
      `부모 원글: ${rootPostText.slice(0, 1800)}`,
      `답글 대상 댓글 URL: ${target.url || ""}`,
      `답글 대상 댓글: ${targetText.slice(0, 1800)}`,
    ];
  }
  const quotePostUrl = normalizeXStatusUrl(target.quotePostUrl || "");
  const quotePostText = cleanSocialText(target.quotePostText || "");
  const visibleMediaCount = Math.max(0, Number(target.visibleMediaCount || target.mediaCount || target.quoteMediaCount || 0));
  return [
    `원문 URL: ${target.url || ""}`,
    `원문: ${targetText.slice(0, 1800)}`,
    quotePostUrl ? `인용 원문 URL: ${quotePostUrl}` : null,
    quotePostText ? `인용 원문: ${quotePostText.slice(0, 1800)}` : null,
    visibleMediaCount > 0 ? `화면에 보이는 첨부/인용 미디어: ${visibleMediaCount}개` : null,
    visibleMediaCount > 0 ? "첨부나 인용 미디어가 이미 보이므로 무엇인지 모르는 듯 되묻지 마라. 단, 원문 작성자가 직접 물은 내용을 함께 궁금해하는 맞장구는 가능하다." : null,
  ].filter(Boolean);
}

function assessTerafabxParentContextMismatch(target = {}, reply = "") {
  const rootPostText = cleanSocialText(target.rootPostText || "");
  const targetText = cleanSocialText(target.targetText || target.text || "");
  const comment = cleanSocialText(reply);
  const praisesVisibleSubject = /귀엽|기특|예쁘|멋지|착하|사랑스럽/.test(targetText);
  const hasVisibleSubject = Math.max(0, Number(target.visibleMediaCount || target.mediaCount || target.quoteMediaCount || 0)) > 0
    || /(?:이|그|저)\s*(?:짤|사진|영상|장면|아이|애|강아지|고양이)|(?:이거|그거|저거)/.test(targetText);
  const asksUnknownSubject = /도대체\s*(?:어떤|누구|무슨)|(?:어떤|누구|무슨)\s*.{0,14}(?:길래|인가요|일까요|거예요)|(?:무엇이|뭐가|뭔지).{0,14}(?:궁금|나올지|보일지)/.test(comment);
  const targetAsksSameUnknown = /(?:뭐|뭔|무엇|어떤|누구|무슨|어떻게).{0,24}(?:궁금|인가|일까|거야|건데|하는|함)|(?:궁금|어떻게\s*하)/.test(targetText);
  const mismatch = Boolean(asksUnknownSubject && !targetAsksSameUnknown && ((rootPostText && praisesVisibleSubject) || hasVisibleSubject));
  return {
    ok: !mismatch,
    reason: mismatch ? "부모 원글에 보이는 대상을 모르는 듯 되묻는 문구" : null,
  };
}

