function clearTerafabxOwnPostReplyXIdleCleanup() {
  if (!terafabxOwnPostReplyXIdleCleanupTimer) return;
  clearTimeout(terafabxOwnPostReplyXIdleCleanupTimer);
  terafabxOwnPostReplyXIdleCleanupTimer = null;
}

function scheduleTerafabxOwnPostReplyXIdleCleanup() {
  clearTerafabxOwnPostReplyXIdleCleanup();
  terafabxOwnPostReplyXIdleCleanupTimer = setTimeout(async () => {
    terafabxOwnPostReplyXIdleCleanupTimer = null;
    if (terafabxOwnPostReplyBusy || terafabxOwnPostReplyXWriterQueue.depth > 0) {
      scheduleTerafabxOwnPostReplyXIdleCleanup();
      return;
    }
    const cleanup = await closeTerafabxIsolatedXBrowser("ownReply").catch((error) => ({ error: error.message }));
    logEvent("terafabx_own_post_reply_x_idle_cleanup", {
      idleTtlMs: TERAFABX_OWN_POST_REPLY_X_IDLE_TTL_MS,
      cleanup,
    });
  }, TERAFABX_OWN_POST_REPLY_X_IDLE_TTL_MS);
  terafabxOwnPostReplyXIdleCleanupTimer.unref?.();
}

async function copyXCookiesToPage(page) {
  const source = await getCookieSourcePage();
  try {
    const all = await source.page.send("Network.getAllCookies", {}, 10000);
    const cookies = (all.cookies || [])
      .filter((cookie) => /(^|\.)x\.com$|(^|\.)twitter\.com$|(^|\.)twimg\.com$/.test(String(cookie.domain || "").replace(/^\./, ".")))
      .map((cookie) => ({
        name: cookie.name,
        value: cookie.value,
        domain: cookie.domain,
        path: cookie.path || "/",
        secure: Boolean(cookie.secure),
        httpOnly: Boolean(cookie.httpOnly),
        sameSite: cookie.sameSite,
        expires: cookie.expires,
      }))
      .filter((cookie) => cookie.name && cookie.value);
    if (!cookies.length) throw new Error("복사할 X 로그인 쿠키를 찾지 못했습니다.");
    await page.send("Network.setCookies", { cookies }, 10000);
    logEvent("terafabx_verified_review_x_cookies_copied", { count: cookies.length, port: page.port });
    return { count: cookies.length };
  } finally {
    if (source.closeTab) await source.page.close();
    else {
      try { source.page.ws.close(); } catch {}
    }
  }
}

async function withTerafabxBrowserSetupCleanup(setup, cleanup, onError = null) {
  try {
    return await setup();
  } catch (error) {
    const cleanupResult = await cleanup().catch((cleanupError) => ({ error: cleanupError.message }));
    if (typeof onError === "function") onError(error, cleanupResult);
    throw error;
  }
}

